  ('CHEM 1A', 'CHEM', '1A', 'General Chemistry', 'GEN CHEM', 4, 'Topics covered: atomic structure of matter; reaction stoichiometry; solution stoichiometry; gasses; quantum chemistry and the electronic structure of atoms; chemical bonding (molecular shapes, hybridization, and molecular orbital theory).', 'College of Letters and Science', '{}', '', NULL, '{}', ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CHEM%201A'),
  ('CHEM 1AL', 'CHEM', '1AL', 'General Chemistry Laboratory', 'GEN CHEM LAB', 2, 'Qualitative and quantitative measurements to develop laboratory technique and demonstrate the basic concepts of stoichiometry, chemical bonding, gas laws, chemical equilibrium, and acid-base chemistry.', 'College of Letters and Science', '{}', 'Chemistry 1A or 2A or 3A (may be taken concurrently).', '{"t":"or","kids":[{"t":"course","code":"CHEM 1A","concurrent":true},{"t":"course","code":"CHEM 2A","concurrent":true},{"t":"course","code":"CHEM 3A","concurrent":true}]}'::JSONB, '{}', '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CHEM%201AL'),
  ('CHEM 1B', 'CHEM', '1B', 'General Chemistry', 'GENERAL CHEMISTRY', 3, 'Topics covered: equilibrium; acids, bases, and buffers; thermochemistry (energy, enthalpy, entropy, and free energy); electrochemistry.', 'College of Letters and Science', '{}', 'CHEM 1A, CHEM 2A or CHEM 3A with a minimum grade of C-.', '{"t":"or","kids":[{"t":"course","code":"CHEM 1A","concurrent":false},{"t":"course","code":"CHEM 2A","concurrent":false},{"t":"course","code":"CHEM 3A","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CHEM%201B'),
  ('CHEM 1BL', 'CHEM', '1BL', 'General Chemistry Laboratory', 'GEN CHEM LAB', 2, 'Qualitative and quantitative measurements to develop laboratory technique and demonstrate basic concepts of thermochemistry, electrochemistry, chemical kinetics and atomic spectroscopy.', 'College of Letters and Science', '{}', 'CHEM 1A or 2A or 3A with a minimum grade of C-; CHEM 1B or 2B or 3B (may be taken concurrently).', '{"t":"and","kids":[{"t":"or","kids":[{"t":"course","code":"CHEM 1A","concurrent":false},{"t":"course","code":"CHEM 2A","concurrent":false},{"t":"course","code":"CHEM 3A","concurrent":false}]},{"t":"or","kids":[{"t":"course","code":"CHEM 1B","concurrent":true},{"t":"course","code":"CHEM 2B","concurrent":true},{"t":"course","code":"CHEM 3B","concurrent":true}]}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CHEM%201BL'),
  ('CHEM 1C', 'CHEM', '1C', 'General Chemistry', 'GEN CHEM', 3, 'Topics covered: kinetics; intermolecular forces, liquids and solids; properties of solutions; transition metals and coordination complexes; organic chemistry and polymers; nuclear chemistry.', 'College of Letters and Science', '{}', 'CHEM 1B, CHEM 2B or CHEM 3B with a minimum grade of C-.', '{"t":"or","kids":[{"t":"course","code":"CHEM 1B","concurrent":false},{"t":"course","code":"CHEM 2B","concurrent":false},{"t":"course","code":"CHEM 3B","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Fall', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CHEM%201C'),
  ('CHEM 1CL', 'CHEM', '1CL', 'General Chemistry Laboratory', 'GEN CHEM LAB', 2, 'Qualitative and quantitative measurements to develop laboratory technique and demonstrate the basic concepts of solutions, intermolecular forces, colligative properties, and synthetic organic inorganic chemistry.', 'College of Letters and Science', '{}', 'Chemistry 1B or 2B or 3B with a minimum grade of C-; Chemistry 1C or 2C or 3C (may be taken concurrently).', '{"t":"and","kids":[{"t":"or","kids":[{"t":"course","code":"CHEM 1B","concurrent":false},{"t":"course","code":"CHEM 2B","concurrent":false},{"t":"course","code":"CHEM 3B","concurrent":false}]},{"t":"or","kids":[{"t":"course","code":"CHEM 1C","concurrent":true},{"t":"course","code":"CHEM 2C","concurrent":true},{"t":"course","code":"CHEM 3C","concurrent":true}]}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CHEM%201CL'),
  ('CHEM 2A', 'CHEM', '2A', 'General Chemistry (Honors)', 'GEN CHEM-HONORS', 3, 'The sequence of topics will be similar to that in Chemistry 1A. Calculus will be used as needed, at the level of the concurrent Mathematics 3A course.', 'College of Letters and Science', '{}', '', NULL, '{}', '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CHEM%202A'),
  ('CHEM 2B', 'CHEM', '2B', 'General Chemistry (Honors)', 'GEN CHEM - HONORS', 3, 'Thermodynamics (first and second law), electrochemistry, chemical kinetics, atomic and molecular structure, and chemical bonding.', 'College of Letters and Science', '{}', 'CHEM 2A or CHEM 1A or CHEM 3A with a minimum grade of B.', '{"t":"or","kids":[{"t":"course","code":"CHEM 2A","concurrent":false},{"t":"course","code":"CHEM 1A","concurrent":false},{"t":"course","code":"CHEM 3A","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of B']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CHEM%202B'),
  ('CHEM 2C', 'CHEM', '2C', 'General Chemistry (Honors)', 'GEN CHEM (HONORS)', 3, 'Structure and dynamics of the elements and their compounds. Aspects of technology and environmental problems.', 'College of Letters and Science', '{}', 'CHEM 2B or CHEM 1B or CHEM 3B with a minimum grade of B.', '{"t":"or","kids":[{"t":"course","code":"CHEM 2B","concurrent":false},{"t":"course","code":"CHEM 1B","concurrent":false},{"t":"course","code":"CHEM 3B","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of B']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CHEM%202C'),
  ('CHEM 3A', 'CHEM', '3A', 'General Chemistry (Majors)', 'GEN CHEM MAJORS', 4, 'Topics covered: atomic structure of matter; reaction stoichiometry; solution stoichiometry; gasses; quantum chemistry and the electronic structure of atoms; chemical bonding (molecular shapes, hybridization, and molecular orbital theory). First quarter of general chemistry intended for Chemistry Pre-Majors and Chemical Engineering Majors and others requiring a strong basis in chemistry.', 'College of Letters and Science', ARRAY['PRCHM', 'CHEME', 'CHBCS']::TEXT[], 'None', NULL, '{}', ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CHEM%203A'),
  ('CHEM 3B', 'CHEM', '3B', 'General Chemistry (Majors)', 'GEN CHEM MAJORS', 3, 'Topics covered: equilibrium; acids, bases, and buffers; thermochemistry (energy, enthalpy, entropy, and free energy); electrochemistry. Second quarter of general chemistry intended for Chemistry Pre-Majors and Chemical Engineering Majors and others requiring a strong basis in chemistry.', 'College of Letters and Science', ARRAY['PRCHM', 'CHEME', 'CHBCS']::TEXT[], 'CHEM 1A, CHEM 2A, or CHEM 3A with a minimum grade of C-.', '{"t":"or","kids":[{"t":"course","code":"CHEM 1A","concurrent":false},{"t":"course","code":"CHEM 2A","concurrent":false},{"t":"course","code":"CHEM 3A","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CHEM%203B'),
  ('CHEM 3C', 'CHEM', '3C', 'General Chemistry (Majors)', 'GEN CHEM MAJORS', 3, 'Topics covered: kinetics; intermolecular forces, liquids and solids; properties of solutions; transition metals and coordination complexes; organic chemistry and polymers; nuclear chemistry.  Third quarter of general chemistry intended for Chemistry Pre-Majors and Chemical Engineering Majors and others requiring a strong basis in chemistry.', 'College of Letters and Science', ARRAY['PRCHM', 'CHEME', 'CHBCS']::TEXT[], 'CHEM 1B, CHEM 2B, or CHEM 3B with a minimum grade of C-.', '{"t":"or","kids":[{"t":"course","code":"CHEM 1B","concurrent":false},{"t":"course","code":"CHEM 2B","concurrent":false},{"t":"course","code":"CHEM 3B","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CHEM%203C'),
  ('CMPSC 1', 'CMPSC', '1', 'Seminar on the Field of Computer Science', 'SEMINAR COMP SCI', 1, 'Overviews the potential of, and opportunities available from, the field of computer science. Topics include an overview of how computers work and the interesting ways in which computers can be applied to solve important and high-impact technological, social, and cutting-edge research problems.', 'College of Engineering', ARRAY['CMPSC']::TEXT[], 'Open to computer science majors only.', NULL, ARRAY['Open to computer science majors only']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%201'),
  ('CMPSC 2', 'CMPSC', '2', 'Computational Thinking for Scientists', 'COMP THINKING', 4, 'Introduction to the central concepts of computer science as they apply to a wide variety of human endeavors, including natural and physical sciences. Topics that interrelate central ideas from algorithms, performance and complexity, data structures, concurrency, languages and abstractions will be studied.', 'College of Engineering', '{}', 'Math 4A with a grade of C or better.', '{"t":"course","code":"MATH 4A","concurrent":false}'::JSONB, ARRAY['with a grade of C or better']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%202'),
  ('CMPSC 4', 'CMPSC', '4', 'Computer Science Boot Camp', 'CS BOOT CAMP', 4, 'An introduction to computational thinking, computing, data management, and problem solving using computers, for non-majors. Topics include coding basics, representing code and data using a computer, and applications of computing that are important to society.', 'College of Engineering', '{}', '', NULL, '{}', '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%204'),
  ('CMPSC 5A', 'CMPSC', '5A', 'Introduction to Data Science 1', 'INTRO DATA SCI 1', 4, 'Introduction to data science methods and Python programming language for students with little to no experience in the subjects. Topics include foundational programming concepts, problem-solving strategies and code design, and data science concepts as table operations, exploratory data analysis, basic probability.', 'College of Engineering', '{}', '', NULL, '{}', ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%205A'),
  ('CMPSC 5B', 'CMPSC', '5B', 'Introduction to Data Science 2', 'INTRO DATA SCI 2', 4, 'Students explore the data science lifecycle, including question formulation, data collection and cleaning, exploratory data analysis and visualization, statistical inference and prediction, and decision-making. The course focus is on transforming and analyzing data; machine learning methods including regression, classification and clustering; principles behind data visualizations; concepts of measurement error and prediction; and techniques for scalable data processing.', 'College of Engineering', '{}', 'Computer Science 5A or Computer Science 8 or ECE 3 with a grade of C or better.', '{"t":"or","kids":[{"t":"course","code":"CMPSC 5A","concurrent":false},{"t":"course","code":"CMPSC 8","concurrent":false},{"t":"course","code":"ECE 3","concurrent":false}]}'::JSONB, ARRAY['with a grade of C or better']::TEXT[], ARRAY['Fall', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%205B'),
  ('CMPSC 8', 'CMPSC', '8', 'Introduction to Computer Science', 'INTRO TO COMP SCI', 4, 'Introduction to computer program development for students with little to no programming experience. Basic programming concepts, variables and expressions, data and control structures, algorithms, debugging, program design, and documentation.', 'College of Engineering', '{}', '', NULL, '{}', ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%208'),
  ('CMPSC 9', 'CMPSC', '9', 'Intermediate Python Programming', 'INTERMEDIATE PYTHON', 4, 'Intermediate topics in Computer Science using the Python programming language. Topics include object oriented programming, runtime analysis, data structures, and software testing methodologies.', 'College of Engineering', '{}', 'CMPSC 8 or CMPSC W8 or ENGR 3 or ENGR W3 or ECE 3 with a grade of C or better.', '{"t":"or","kids":[{"t":"course","code":"CMPSC 8","concurrent":false},{"t":"course","code":"ENGR 3","concurrent":false},{"t":"course","code":"ECE 3","concurrent":false}]}'::JSONB, ARRAY['with a grade of C or better']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%209'),
  ('CMPSC 11', 'CMPSC', '11', 'Programming Language Laboratory', 'PROG LANG LAB', 1, 'A self-paced course to allow a student who already possesses a working knowledge of at least one programming language an opportunity to learn other languages of interest. Each section studies a different programming language.', 'College of Engineering', '{}', 'Knowledge of at least one programming language.', NULL, ARRAY['Knowledge of at least one programming language']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%2011'),
  ('CMPSC 11C', 'CMPSC', '11C', 'Programming Language Laboratory', 'PROGRAM LANG LAB', 2, 'A self-paced course to allow a student who already possesses a working knowledge of at least one programming language an opportunity to learn other languages of interest. Each section studies a different language.', 'College of Engineering', '{}', 'knowledge of at least one programming language. sections not always offered', NULL, ARRAY['knowledge of at least one programming language', 'sections not always offered']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%2011C'),
  ('CMPSC 16', 'CMPSC', '16', 'Problem Solving with Computers I', 'PROBLEM SOLVING I', 4, 'Fundamental building blocks for solving problems using computers. Topics include basic computer organization and programming constructs: memory CPU, binary arithmetic, variables, expressions, statements, conditionals, iteration, functions, parameters, recursion, primitive and composite data types, and basic operating system and debugging tools.', 'College of Engineering', '{}', 'Mathematics 3A or 2A with a grade of C or better (may be taken concurrently), CS 8 or Engineering 3 or ECE 3 with a grade of C or better, or significant prior programming experience.', '{"t":"and","kids":[{"t":"or","kids":[{"t":"course","code":"MATH 3A","concurrent":true},{"t":"course","code":"MATH 2A","concurrent":true}]},{"t":"or","kids":[{"t":"course","code":"CMPSC 8","concurrent":false},{"t":"course","code":"ENGR 3","concurrent":false},{"t":"course","code":"ECE 3","concurrent":false}]}]}'::JSONB, ARRAY['significant prior programming experience', 'with a grade of C or better', 'with a grade of C or better', '[curated] Two comma-separated requirements, each internally an alternation; the comma is a conjunction here, not a disjunction.']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%2016'),
  ('CMPSC 24', 'CMPSC', '24', 'Problem Solving with Computers II', 'PROBLEM SOLVING II', 4, 'Intermediate building blocks for solving problems using computers. Topics include intermediate object-oriented programming, data structures, object-oriented design, algorithms for manipulating these data structures and their run-time analyses. Data structures introduced include stacks, queues, lists, trees, and sets.', 'College of Engineering', '{}', 'Computer Science 16 with a grade of C or better; and Mathematics 3B or 2B with a grade of C or better (may be taken concurrently).', '{"t":"and","kids":[{"t":"course","code":"CMPSC 16","concurrent":false},{"t":"or","kids":[{"t":"course","code":"MATH 3B","concurrent":true},{"t":"course","code":"MATH 2B","concurrent":true}]}]}'::JSONB, ARRAY['with a grade of C or better', 'with a grade of C or better']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%2024'),
  ('CMPSC 24A', 'CMPSC', '24A', 'Problem Solving with Computers II', 'PROBLEM SOLVING II', 4, 'Intermediate building blocks for solving problems using computers. Topics include data structures, object-oriented design and development, algorithms for manipulating these data structures and their runtime analyses. Data structures introduced include stacks, queues, lists, trees, and sets.', 'College of Engineering', '{}', 'Computer Science 16 with a grade of C or better; and Mathematics 3B or 2B with a grade of C or better (may be taken concurrently).', '{"t":"and","kids":[{"t":"course","code":"CMPSC 16","concurrent":false},{"t":"or","kids":[{"t":"course","code":"MATH 3B","concurrent":true},{"t":"course","code":"MATH 2B","concurrent":true}]}]}'::JSONB, ARRAY['with a grade of C or better', 'with a grade of C or better']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%2024A'),
  ('CMPSC 32', 'CMPSC', '32', 'Object Oriented Design and Implementation', 'OBJ ORIENT DESIGN', 4, 'Advanced topics in object-oriented computing. Topics include encapsulation, data hiding, inheritance, polymorphism, compilation, linking and loading, memory management, and debugging; recent advances in design and development tools, practices, libraries, and operating system support.', 'College of Engineering', '{}', 'Computer Science 24 with a grade of C or better', '{"t":"course","code":"CMPSC 24","concurrent":false}'::JSONB, ARRAY['with a grade of C or better']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%2032'),
  ('CMPSC 40', 'CMPSC', '40', 'Foundations of Computer Science', 'FOUNDATION COMP SCI', 5, 'Introduction to the theoretical underpinnings of computer science. Topics include propositional predicate logic, set theory, functions and relations, counting, mathematical induction and recursion (generating functions).', 'College of Engineering', '{}', 'Computer Science 16 with a grade of C or better and Mathematics 4A with a grade of C or better.', '{"t":"and","kids":[{"t":"course","code":"CMPSC 16","concurrent":false},{"t":"course","code":"MATH 4A","concurrent":false}]}'::JSONB, ARRAY['with a grade of C or better', 'with a grade of C or better']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%2040'),
  ('CMPSC 41', 'CMPSC', '41', 'Discrete Mathematics for Computer Science', 'Discrete Mathematics for Computer Science', 4, 'Introduces the mathematical foundations of computer science, including logic, set theory, functions, counting, induction, recursion and proof techniques, with a focus on applying these concepts to computational problems.', 'College of Engineering', '{}', '', NULL, ARRAY['[new course] New for 2026-27. Required for Computer Engineering, in place of CMPSC 40. Not yet in the General Catalog, so it has no published prerequisites or quarter offerings here -- check GOLD.']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026', 'New for 2026-27. Required for Computer Engineering, in place of CMPSC 40. Not yet in the General Catalog, so it has no published prerequisites or quarter offerings here -- check GOLD.']::TEXT[], 'UCSB GEAR 2026-27 (Computer Engineering, p. 20) and ce.ucsb.edu/undergrad/curriculum', 'https://www.ce.ucsb.edu/undergrad/curriculum', 'UCSB GEAR 2026-27 (Computer Engineering, p. 20) and ce.ucsb.edu/undergrad/curriculum', 'https://www.ce.ucsb.edu/undergrad/curriculum'),
  ('CMPSC 64', 'CMPSC', '64', 'Computer Organization and Logic Design', 'COMP ORGANIZATION', 4, 'Assembly language programming and advanced computer organization; Digital logic design topics including gates, combinational circuits, flip-flops, and the design and analysis of sequential circuits.', 'College of Engineering', ARRAY['CMPSC', 'CPSCI']::TEXT[], 'Computer Science 16 with a grade of C or better; and Mathematics 3C or 4A with a grade of C or better.', '{"t":"and","kids":[{"t":"course","code":"CMPSC 16","concurrent":false},{"t":"or","kids":[{"t":"course","code":"MATH 3C","concurrent":false},{"t":"course","code":"MATH 4A","concurrent":false}]}]}'::JSONB, ARRAY['with a grade of C or better', 'with a grade of C or better']::TEXT[], ARRAY['Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%2064'),
  ('CMPSC 110', 'CMPSC', '110', 'Introduction to Research in Computer Science', 'INTRO RESEARCH CS', 4, 'Defining a CS research problem, finding and reading technical papers, oral communication, technical writing, and independent learning. Course participants work in teams as they apprentice with a CS research group to propose an original research problem and write a research proposal.', 'College of Engineering', '{}', 'Computer Science 40 and Computer Science 32; consent of instructor.', '{"t":"and","kids":[{"t":"course","code":"CMPSC 40","concurrent":false},{"t":"course","code":"CMPSC 32","concurrent":false}]}'::JSONB, ARRAY['consent of instructor']::TEXT[], ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20110'),
  ('CMPSC 111', 'CMPSC', '111', 'Introduction to Computational Science', 'INT COMPUTAT SCI', 4, 'Introduction to the numerical algorithms that form the foundations of data science, machine learning, and computational science and engineering. Matrix computation, linear equation systems, eigenvalue and singular value decompositions, numerical optimization. The informed use of mathematical software environments and libraries, such as python/numpy/scipy.', 'College of Engineering', ARRAY['CMPSC']::TEXT[], 'Mathematics 4B with a grade of C or better; Mathematics 6A with a grade of C or better; Computer Science 24 with a grade of C or better.', '{"t":"and","kids":[{"t":"course","code":"MATH 4B","concurrent":false},{"t":"course","code":"MATH 6A","concurrent":false},{"t":"course","code":"CMPSC 24","concurrent":false}]}'::JSONB, ARRAY['with a grade of C or better', 'with a grade of C or better', 'with a grade of C or better']::TEXT[], ARRAY['Fall', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20111'),
  ('CMPSC 123', 'CMPSC', '123', 'Overview of Computer Systems: Hardware and Software', 'OVER OF COMP SYS', 4, 'Basic computer architecture: CPU, memory, I/O. Basic operating systemsConcepts: processes, synchronization, memory management, virtual memory, file systems.', 'College of Engineering', '{}', 'Computer Science 32; or Computer Science 20 and 60.', '{"t":"or","kids":[{"t":"course","code":"CMPSC 32","concurrent":false},{"t":"and","kids":[{"t":"course","code":"CMPSC 20","concurrent":false},{"t":"course","code":"CMPSC 60","concurrent":false}]}]}'::JSONB, '{}', '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20123'),
  ('CMPSC 130A', 'CMPSC', '130A', 'Data Structures and Algorithms', 'DATA STRUCT ALGORTH', 4, 'Data structures and applications with proofs of correctness and analysis. Hash Tables, Priority Queues (heaps); Balanced Search Trees. Graph Traversal techniques and their applications.', 'College of Engineering', ARRAY['CMPSC', 'CMPEN', 'EE']::TEXT[], 'Pre-requisites: CMPSC 40 or MATH 8 with a grade of C or better; CMPSC 24 or CMPSC 9 with a grade of C or better; PSTAT 120A or ECE 139 (may be taken concurrently with CMPSC 130A); open to computer science, computer engineering, and electrical engineering majors only.', '{"t":"and","kids":[{"t":"or","kids":[{"t":"course","code":"CMPSC 40","concurrent":false},{"t":"course","code":"MATH 8","concurrent":false}]},{"t":"or","kids":[{"t":"course","code":"CMPSC 24","concurrent":false},{"t":"course","code":"CMPSC 9","concurrent":false}]},{"t":"or","kids":[{"t":"course","code":"PSTAT 120A","concurrent":true},{"t":"course","code":"ECE 139","concurrent":true}]}]}'::JSONB, ARRAY['open to computer science, computer engineering, and electrical engineering majors only', 'with a grade of C or better', 'with a grade of C or better']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20130A'),
  ('CMPSC 130B', 'CMPSC', '130B', 'Data Structures and Algorithms II', 'DATA STRUCT ALG II', 4, 'Design and analysis of computer algorithms. Correctness proofs and solution of recurrence relations. Design techniques; divide and conquer, greedy strategies, dynamic programming. Applications of techniques to problems from several disciplines. NP - completeness.', 'College of Engineering', '{}', 'Computer Science 130A.', '{"t":"course","code":"CMPSC 130A","concurrent":false}'::JSONB, '{}', ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20130B'),
  ('CMPSC 132', 'CMPSC', '132', 'Algorithms Engineering', 'Algorithms Engineer', 4, 'Applying theoretical knowledge about algorithms, data structures, and complexity to performing the complete process of analyzing a computational problem, estimating the running time of suggested solutions, and implementing an effective and correct program for the computational problem.', 'College of Engineering', ARRAY['CMPSC', 'CMPEN', 'CMPCS']::TEXT[], '', NULL, '{}', ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20132'),
  ('CMPSC 134', 'CMPSC', '134', 'Randomized Algorithms', 'Random Algorithms', 4, 'Covers advanced algorithmic ideas, focusing on randomized algorithms.  Explores how randomization can be used to make algorithms simpler and more efficient, and to understand the probabilistic analysis of algorithms.', 'College of Engineering', '{}', 'CMPSC 130B with a letter grade of B or better.', '{"t":"course","code":"CMPSC 130B","concurrent":false}'::JSONB, ARRAY['with a letter grade of B or better']::TEXT[], ARRAY['Fall', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20134'),
  ('CMPSC 138', 'CMPSC', '138', 'Automata and Formal Languages', 'AUT & FORML LANG', 4, 'Formal languages; finite automata and regular expressions; properties of regular languages; pushdown automata and context-free grammars; properties of context-free languages; introduction to Turing machines and computability.', 'College of Engineering', ARRAY['CMPSC', 'CMPEN', 'CPSCI']::TEXT[], 'Computer Science 40 with a grade of C or better; open to Computer Science and Computer Engineering majors only.', '{"t":"course","code":"CMPSC 40","concurrent":false}'::JSONB, ARRAY['open to Computer Science and Computer Engineering majors only', 'with a grade of C or better']::TEXT[], ARRAY['Fall', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20138'),
  ('CMPSC 140', 'CMPSC', '140', 'Parallel Scientific Computing', 'PARA SCI COMP', 4, 'Fundamentals of high performance computing and parallel algorithm design for numerical computation. Topics include parallel architectures and clusters, parallel programming with message-passing libraries and threads, program parallelization methodologies, parallel performance evaluation and optimization, parallel numerical algorithms and applications with different performance tradeoffs.', 'College of Engineering', '{}', 'Mathematics 4B with a grade of C or better; Mathematics 6A with a grade of C or better; Computer Science 130A.', '{"t":"and","kids":[{"t":"course","code":"MATH 4B","concurrent":false},{"t":"course","code":"MATH 6A","concurrent":false},{"t":"course","code":"CMPSC 130A","concurrent":false}]}'::JSONB, ARRAY['with a grade of C or better', 'with a grade of C or better']::TEXT[], ARRAY['Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20140'),
  ('CMPSC 148', 'CMPSC', '148', 'Computer Science Project', 'COMP SCI PROJECT', 4, 'Team-based project development. Topics include software engineering and professional development practices, interface design, advanced library support; techniques for team oriented design and development, testing and test driven development, and software reliability and robustness. Students present and demonstrate final projects.', 'College of Engineering', ARRAY['CMPSC', 'CPSCI']::TEXT[], 'Computer Science 32 with a grade of C or better; open to Computer Science majors only.', '{"t":"course","code":"CMPSC 32","concurrent":false}'::JSONB, ARRAY['open to Computer Science majors only', 'with a grade of C or better']::TEXT[], ARRAY['Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20148'),
  ('CMPSC 153A', 'CMPSC', '153A', 'Hardware/Software Interface', 'HRDW/SFTW INTERFACE', 4, 'Design and coding of embedded programs. Real-time constraints and management of resources. Practical I/O interfaces and protocols, polling, interrupt maintenance, atomic code, blocking and non-blocking tasks. Static and dynamic task scheduling under real-time and limited resource constraints.', 'College of Engineering', ARRAY['CMPSC', 'CMPEN', 'EE']::TEXT[], 'Upper division standing in Computer Science, ComputerEngineering, or Electrical Engineering. Familiarity with C, FiniteAutomata, and Computer Architecture.', NULL, ARRAY['Upper division standing in Computer Science, ComputerEngineering, or Electrical Engineering', 'Familiarity with C, FiniteAutomata, and Computer Architecture']::TEXT[], ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20153A'),
  ('CMPSC 154', 'CMPSC', '154', 'Computer Architecture', 'COMPUTER ARCHITECT', 4, 'Introduction to the architecture of computer systems. Topics include: central processing units, memory systems, channels and controllers, peripheral devices, interrupt systems, software versus hardware tradeoffs.', 'College of Engineering', ARRAY['CMPSC']::TEXT[], 'Computer Science 32 with a grade of C or better; Computer Science 64 with a grade of C or better.', '{"t":"and","kids":[{"t":"course","code":"CMPSC 32","concurrent":false},{"t":"course","code":"CMPSC 64","concurrent":false}]}'::JSONB, ARRAY['with a grade of C or better', 'with a grade of C or better']::TEXT[], ARRAY['Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20154'),
  ('CMPSC 156', 'CMPSC', '156', 'Advanced Applications Programming', 'ADV APP PROGRAM', 4, 'Advanced application programming using a high-level, virtual-machine-based language. Topics include generic programming, exception handling, automatic memory management, and application development, management, and maintenance tools, third-party library use, version control, software testing, issue tracking, code review, and working with legacy code.', 'College of Engineering', ARRAY['CMPSC', 'CMPEN', 'CPSCI']::TEXT[], 'Computer Science 24 and 32 with a grade of C or better; open to Computer Science and Computer Engineering majors only.', '{"t":"and","kids":[{"t":"course","code":"CMPSC 24","concurrent":false},{"t":"course","code":"CMPSC 32","concurrent":false}]}'::JSONB, ARRAY['open to Computer Science and Computer Engineering majors only', 'with a grade of C or better']::TEXT[], ARRAY['Fall', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20156'),
  ('CMPSC 160', 'CMPSC', '160', 'Translation of Programming Languages', 'TRANS PROG LANG', 4, 'Study of the structure of compilers. Topics include: lexical analysis; syntax analysis including LL and LR parsers; type checking; run-time environments; intermediate code generation; and compiler-construction tools.', 'College of Engineering', ARRAY['CMPSC', 'CMPEN', 'CPSCI']::TEXT[], 'Computer Science 64 or Electrical Engineering 154 or Electrical Engineering 154A; Computer Science 130A; and Computer Science 138; open to computer science and computer engineering majors only.', '{"t":"and","kids":[{"t":"or","kids":[{"t":"course","code":"CMPSC 64","concurrent":false},{"t":"course","code":"ECE 154","concurrent":false},{"t":"course","code":"ECE 154A","concurrent":false}]},{"t":"course","code":"CMPSC 130A","concurrent":false},{"t":"course","code":"CMPSC 138","concurrent":false}]}'::JSONB, ARRAY['open to computer science and computer engineering majors only']::TEXT[], ARRAY['Fall', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20160'),
  ('CMPSC 162', 'CMPSC', '162', 'Programming Languages', 'PROGRAM LANGUAGES', 4, 'Concepts of programming languages: scopes, parameter passing, storage management; control flow, exception handling; encapsulation and modularization mechanisms; reusability through genericity and inheritance; type systems; programming paradigms (imperative, object-oriented, functional, and others). Emerging programming languages and their development infrastructures.', 'College of Engineering', ARRAY['CMPSC', 'CMPEN', 'CPSCI']::TEXT[], 'Computer Science 130A and 138; open to computer science and computer engineering majors only.', '{"t":"and","kids":[{"t":"course","code":"CMPSC 130A","concurrent":false},{"t":"course","code":"CMPSC 138","concurrent":false}]}'::JSONB, ARRAY['open to computer science and computer engineering majors only']::TEXT[], ARRAY['Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20162'),
  ('CMPSC 165A', 'CMPSC', '165A', 'Artificial Intelligence', 'ARTIF INTELLIGENCE', 4, 'Introduction to the field of artificial intelligence, which seeks to understand and build intelligent computational systems. Topics include intelligent agents, problem solving and heuristic search, knowledge representation and reasoning, uncertainty and probabilistic reasoning, machine learning, reinforcement learning, and responsible AI.', 'College of Engineering', ARRAY['CMPSC', 'CPSCI', 'CMPEN', 'EE']::TEXT[], 'Computer Science 130A', '{"t":"course","code":"CMPSC 130A","concurrent":false}'::JSONB, '{}', ARRAY['Fall', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20165A'),
  ('CMPSC 165B', 'CMPSC', '165B', 'Machine Learning', 'MACHINE LEARNING', 4, 'Covers the most important techniques of machine learning (ML) and includes discussions of: well-posed learning problems; artificial neural networks; concept learning and general to specific ordering; decision tree learning; genetic algorithms; Bayesian learning; analytical learning; and others.', 'College of Engineering', '{}', 'Computer Science 130A.', '{"t":"course","code":"CMPSC 130A","concurrent":false}'::JSONB, '{}', ARRAY['Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20165B'),
  ('CMPSC 170', 'CMPSC', '170', 'Operating Systems', 'OPERATING SYSTEMS', 4, 'Basic concepts of operating systems. The notion of a process; interprocess communication and synchronization; input-output, file systems, memory management.', 'College of Engineering', ARRAY['CMPSC', 'CMPEN', 'EE', 'CPSCI']::TEXT[], 'Computer Science 130A; and, Computer Science 154 or ECE 154A (may be taken concurrently); open to computer science, computer engineering or electrical engineering majors only.', '{"t":"and","kids":[{"t":"course","code":"CMPSC 130A","concurrent":false},{"t":"or","kids":[{"t":"course","code":"CMPSC 154","concurrent":true},{"t":"course","code":"ECE 154A","concurrent":true}]}]}'::JSONB, ARRAY['open to computer science, computer engineering or electrical engineering majors only']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20170'),
  ('CMPSC 171', 'CMPSC', '171', 'Distributed Systems', 'DISTRD SYSTEMS', 4, 'Distributed systems architecture, distributed programming, network of computers, message passing, remote procedure calls, group communication, naming and membership problems, asynchrony, logical time, consistency, fault-tolerance, and recovery.', 'College of Engineering', '{}', 'Computer Science 130A.', '{"t":"course","code":"CMPSC 130A","concurrent":false}'::JSONB, '{}', ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20171'),
  ('CMPSC 172', 'CMPSC', '172', 'Software Engineering', 'SOFTWARE ENGINEERNG', 4, 'Software engineering is concerned with long-term, large-scale programming projects. Software management, cost estimates, problem specification and analysis, system design techniques, system testing and performance evaluation, and system maintenance. Students will design, manage, and implement a medium-sized project.', 'College of Engineering', ARRAY['CMPSC', 'CPSCI', 'CMPEN']::TEXT[], 'Computer Science 130A. Open to Computer Science or Computer Engineering majors only, or by consent of department.', '{"t":"course","code":"CMPSC 130A","concurrent":false}'::JSONB, ARRAY['Open to Computer Science or Computer Engineering majors only, or by consent of department']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20172'),
  ('CMPSC 174A', 'CMPSC', '174A', 'Fundamentals of Database Systems', 'FUND DATABASE SYS', 4, 'Database system architectures, relational data model, relational algebra, relational calculus, SQL, QBE, query processing, integrity constraints (key constraints, referential integrity), database design, ER and object- oriented data model, functional dependence, lossless join and dependency preserving decompositions, Boyce-Codd and Third Normal Forms.', 'College of Engineering', '{}', 'Computer Science 130A.', '{"t":"course","code":"CMPSC 130A","concurrent":false}'::JSONB, '{}', ARRAY['Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20174A'),
  ('CMPSC 174B', 'CMPSC', '174B', 'Design and Implementation Techniques of Database Systems', 'DES & IMP DTBS SYS', 4, 'Queries and processing, optimizer, cost models, execution plans, rewriting rules, access methods, spatial indexing; transactions, ACID properties, concurrency control, serializability, two-phase locking, timestamping, logging,checkpointing, transaction abort and commit, crash recovery; distributed databases.', 'College of Engineering', '{}', 'Computer Science 130B.', '{"t":"course","code":"CMPSC 130B","concurrent":false}'::JSONB, '{}', ARRAY['Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20174B'),
  ('CMPSC 174N', 'CMPSC', '174N', 'Introduction to Databases', 'INTRO TO DATABASES', 4, 'ER/object-oriented data modeling, relational data model, database design, query languages (algebra, calculus, SQL, QBE), updates and views, query processing, integrity constraints (key constraints, referential integrity), functional dependence, Boyce-Codd and Third Normal Forms.', 'College of Engineering', '{}', 'Computer Science 130A (may be taken concurrently); or consent of instructor.', '{"t":"course","code":"CMPSC 130A","concurrent":true}'::JSONB, ARRAY['consent of instructor']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20174N'),
  ('CMPSC 176A', 'CMPSC', '176A', 'Introduction to Computer Communication Networks', 'COMP COMM NETWORKS', 4, 'Basic concepts in networking, the OSI model, error detection codes, flow control, routing, medium access control, and high-speed networks.', 'College of Engineering', ARRAY['CMPSC', 'EE', 'CPSCI', 'CMPEN']::TEXT[], 'CMPSC 32 with a grade of C or better; PSTAT 120A or ECE 139; open to computer science, electrical engineering, and computer engineering majors only.', '{"t":"and","kids":[{"t":"course","code":"CMPSC 32","concurrent":false},{"t":"or","kids":[{"t":"course","code":"PSTAT 120A","concurrent":false},{"t":"course","code":"ECE 139","concurrent":false}]}]}'::JSONB, ARRAY['open to computer science, electrical engineering, and computer engineering majors only', 'with a grade of C or better']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20176A'),
  ('CMPSC 176B', 'CMPSC', '176B', 'Network Computing', 'NETWRK COMPUTING', 4, 'Focus on networking and web technologies used in the Internet. The class covers socket programming and web-based techniques that are used to build distributed applications.', 'College of Engineering', '{}', 'Computer Science 176A.', '{"t":"course","code":"CMPSC 176A","concurrent":false}'::JSONB, '{}', '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20176B'),
  ('CMPSC 176C', 'CMPSC', '176C', 'Advanced Topics in Internet Computing', 'ADV TOP INT COMP', 4, 'General overview of wireless and mobile networking, multimedia, security, multicast, quality of service, IPv6, and web caching. During the second half of the course, one or more of the above are studied in greater detail.', 'College of Engineering', '{}', 'Computer Science 176A.', '{"t":"course","code":"CMPSC 176A","concurrent":false}'::JSONB, '{}', ARRAY['Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20176C'),
  ('CMPSC 177', 'CMPSC', '177', 'Computer Security', 'COMPUTER SECURITY', 4, 'Introduction to the basics of computer security and privacy. Analysis of technical difficulties of producing secure computer information systems that provide guaranteed controlled sharing. Examination and critique of current systems, methods, certification.', 'College of Engineering', '{}', 'Computer Science 170 (may be taken concurrently).', '{"t":"course","code":"CMPSC 170","concurrent":true}'::JSONB, '{}', ARRAY['Fall', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20177'),
  ('CMPSC 178', 'CMPSC', '178', 'Introduction to Cryptography', 'INTRO CRYPTOGRAPHY', 4, 'An introduction to the basic concepts and techniques of cryptography and cryptanalysis. Topics include: The Shannon Theory, classical systems, the enigma machine, the data encryption standard, public key systems, digital signatures, file security.', 'College of Engineering', '{}', 'Computer Science 24 with a grade of C or better; Computer Science 40 with a grade of C or better; and PSTAT 120A or 121A or ECE 139 or permission of instructor.', '{"t":"and","kids":[{"t":"course","code":"CMPSC 24","concurrent":false},{"t":"course","code":"CMPSC 40","concurrent":false},{"t":"or","kids":[{"t":"course","code":"PSTAT 120A","concurrent":false},{"t":"course","code":"PSTAT 121A","concurrent":false},{"t":"course","code":"ECE 139","concurrent":false}]}]}'::JSONB, ARRAY['permission of instructor', 'with a grade of C or better', 'with a grade of C or better']::TEXT[], ARRAY['Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20178'),
  ('CMPSC 180', 'CMPSC', '180', 'Computer Graphics', 'COMPUTER GRAPHICS', 4, 'Overview of OpenGL graphics standard, OpenGL statemachine, other 3D graphics libraries, 3D graphicspipeline, 3D transformations and clipping, colormodel, shading model, shadow algorithms, texturing,curves and curved surfaces, graphics hardware,interaction devices and techniques', 'College of Engineering', '{}', 'Computer Science 130A or consent of instructor.', '{"t":"course","code":"CMPSC 130A","concurrent":false}'::JSONB, ARRAY['consent of instructor']::TEXT[], ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20180'),
  ('CMPSC 181', 'CMPSC', '181', 'Introduction to Computer Vision', 'INTRO COMP VISION', 4, 'Overview of computer vision problems and techniques for analyzing the content of images and video. Topics include image formation, edge detection, image segmentation, pattern recognition, texture analysis, optical flow, stereo vision, shape representation and recovery techniques, issues in object recognition, and case studies of practical vision systems.', 'College of Engineering', ARRAY['CHEME', 'CPSCI', 'CMPEN', 'EE', 'CMPSC', 'ME']::TEXT[], 'Upper-division standing in Electrical Engineering, Computer Engineering,Computer Science, Chemical Engineering or Mechanical Engineering.', NULL, ARRAY['Upper-division standing in Electrical Engineering, Computer Engineering,Computer Science, Chemical Engineering or Mechanical Engineering']::TEXT[], ARRAY['Fall', 'Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20181'),
  ('CMPSC 182', 'CMPSC', '182', 'Multimedia Computing', 'MULTIMED COMPUTNG', 4, 'Introduction to multimedia and applications. Topics include streaming media, conferencing, webcasting, digital libraries, multimedia system architectures, standards (including JPEG and MPEG), and multimedia storage and retrieval. A key emphasis is on using the internet for delivery of multimedia data. (First offered 2003-2004)', 'College of Engineering', ARRAY['CMPSC', 'CPSCI']::TEXT[], '', NULL, '{}', '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20182'),
  ('CMPSC 184', 'CMPSC', '184', 'Mobile Application Development', 'MOBILE APP DEV', 4, 'An introduction to programming mobile computing devices. Students will learn about and study the shift in software development from desktop to mobile device applications. Topics will include software engineering and design practices, advances in programming practice, and support tools for mobile application development and testing. Students will develop and deploy mobile applications as part of their course work.', 'College of Engineering', ARRAY['CMPSC', 'CMPEN']::TEXT[], 'Computer Science 56 or Computer Science 156; and Computer Science 130A.', '{"t":"and","kids":[{"t":"or","kids":[{"t":"course","code":"CMPSC 56","concurrent":false},{"t":"course","code":"CMPSC 156","concurrent":false}]},{"t":"course","code":"CMPSC 130A","concurrent":false}]}'::JSONB, '{}', ARRAY['Fall', 'Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20184'),
  ('CMPSC 185', 'CMPSC', '185', 'Human-Computer Interaction', 'HUM-COMP INTERACT', 4, 'The study of human-computer interaction enables system architects to design useful, efficient, and enjoyable computer interfaces. This course teaches the theory, design guidelines, programming practices, and evaluation procedures behind effective human interaction with computers.', 'College of Engineering', ARRAY['CMPSC', 'CPSCI', 'CMPEN', 'EE']::TEXT[], 'Upper division standing; Open to computer science, computer engineering, and electrical engineering majors.', NULL, ARRAY['Open to computer science, computer engineering, and electrical engineering majors', 'Upper division standing']::TEXT[], ARRAY['Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20185'),
  ('CMPSC 186', 'CMPSC', '186', 'Internet of Things (IoT) Systems', 'IoT Systems', 4, 'The Internet of Things (IoT) embeds ordinary physical objects in our environment with digital intelligence -- via sensing, control, communications, and computing capabilities. As such, IoT advances are likely key drivers of the next computing revolution.  This course will teach IoT systems end-to-end, including the fundamentals of IoT devices, software architectures, communication protocols, security approaches, distributed, multi-tier (e.g. sensors, edge, and cloud) programming and deployment considerations needed to support emerging IoT applications.', 'College of Engineering', ARRAY['CMPSC', 'CMPEN', 'CPTCS']::TEXT[], 'CMPSC 32 or CMPSC 130A.', '{"t":"or","kids":[{"t":"course","code":"CMPSC 32","concurrent":false},{"t":"course","code":"CMPSC 130A","concurrent":false}]}'::JSONB, '{}', '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20186'),
  ('CMPSC 188', 'CMPSC', '188', 'Introduction to Natural Language Processing', 'Intro to NLP', 4, 'This NLP course explores AI''s capability to understand human language, focusing on machine learning algorithms and large language models. It covers language modeling, sentiment analysis, tagging, and machine translation, discussing lexical, syntactic, and semantic processing. Key models include Naive Bayes, logistic regression, and neural networks like RNNs and CNNs. It emphasizes empirical analysis of text corpora and how to evaluate the strengths and limitations of statistical tools, including large language models, in NLP.', 'College of Engineering', ARRAY['CMPSC', 'CMPEN']::TEXT[], 'Open to computer science and computer engineering majors only.', NULL, ARRAY['Open to computer science and computer engineering majors only']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20188'),
  ('CMPSC 189A', 'CMPSC', '189A', 'Senior Computer Systems Project', 'SR CMPTR PRJCT', 4, 'This course is the first in the 2-course Computer Science Capstone sequence. Student teams learn about modern software design and engineering techniques and work together to use them and their past educational experiences at UCSB to analyze, specify, design, and prototype innovative solutions to complex, real world problems using computers.', 'College of Engineering', ARRAY['CMPSC', 'CMPEN']::TEXT[], 'Computer Science 48 or 56 or 148 or 156 or 172; Senior standing in computer science or computer engineering.', '{"t":"or","kids":[{"t":"course","code":"CMPSC 48","concurrent":false},{"t":"course","code":"CMPSC 56","concurrent":false},{"t":"course","code":"CMPSC 148","concurrent":false},{"t":"course","code":"CMPSC 156","concurrent":false},{"t":"course","code":"CMPSC 172","concurrent":false}]}'::JSONB, ARRAY['Senior standing in computer science or computer engineering']::TEXT[], ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20189A'),
  ('CMPSC 189B', 'CMPSC', '189B', 'Senior Computer Systems Project', 'SR CMPTR PRJCT', 4, 'This course is the second in the 2-course Computer Science Capstone sequence. Student teams continue their CMPSC 189A effort by evolving their specifications, design, and prototypes of advanced computer science solutions and systems. The students learn about interfaces, software integration, and testing, and prepare advanced demonstrations for public presentation at the end of the sequence.', 'College of Engineering', ARRAY['CMPSC', 'CMPEN']::TEXT[], 'CMPSC 189A; Senior standing in Computer Science or Computer Engineering.', '{"t":"course","code":"CMPSC 189A","concurrent":false}'::JSONB, ARRAY['Senior standing in Computer Science or Computer Engineering']::TEXT[], ARRAY['Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/CMPSC%20189B'),
  ('ECE 1A', 'ECE', '1A', 'Computer Engineering Seminar', 'COMP ENGR SEMINAR', 1, 'Introductory seminar to expose students to a broad range of topics in computer engineering.', 'College of Engineering', ARRAY['PRCME', 'CMPEN']::TEXT[], 'Open to computer engineering majors only.', NULL, ARRAY['Open to computer engineering majors only']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%201A'),
  ('ECE 1B', 'ECE', '1B', 'Ten Puzzling Problems in Computer Engineering', 'PROBLEMS COMP ENG', 1, 'Gaining familiarity with, and motivation to study, the field of computer engineering, through puzzle-like problems that represent a range of challenges facing computer engineers in their daily problem-solving efforts and at the frontiers of research.', 'College of Engineering', ARRAY['PRCME', 'CMPEN']::TEXT[], 'Open to pre-computer engineering and computer engineering majors only.', NULL, ARRAY['Open to pre-computer engineering and computer engineering majors only']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%201B'),
  ('ECE 3', 'ECE', '3', 'Introduction to Python Programming For Engineers', 'INTRO PYTHON PROG', 4, 'This course represents a comprehensive foundation for core ECE topics in signal processing, image analysis, machine learning, optimization and control. The lectures present concepts from linear algebra, such as matrix computations, systems of linear equations, eigenspace decomposition, inner-product, orthogonality, least-squares and linear regression. Students actively engage with the technical materials with an introduction to Python programming and associated hands-on sessions. The materials are be motivated by real-world scenarios ranging from medical imaging to autonomous vehicles, from (miscarriage of) justice to brain-machine interfaces, from music analysis to GPS design.', 'College of Engineering', ARRAY['EE', 'CMPEN']::TEXT[], 'Open to EE and CMPEN majors only.', NULL, ARRAY['Open to EE and CMPEN majors only']::TEXT[], ARRAY['Fall']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%203'),
  ('ECE 5', 'ECE', '5', 'Introduction to Electrical & Computer Engineering', 'INTRO TO ECE', 4, 'Aims at exposing freshmen students to the different sub-fields within Electrical and Computer Engineering. Composed of lectures by different faculty members and a weekly laboratory based on projects that are executed using the Arduino environment.', 'College of Engineering', ARRAY['EE', 'CMPEN']::TEXT[], 'Open only to Electrical Engineering and Computer Engineering majors.', NULL, ARRAY['Open only to Electrical Engineering and Computer Engineering majors']::TEXT[], ARRAY['Fall', 'Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%205'),
  ('ECE 6', 'ECE', '6', 'The Physics of Energy, Information, and Communication', 'PHYS ENGY INFO COMM', 4, 'An introduction to the relationship between the physical nature of matter and modern problems in energy harvesting, energy storage, information storage, and communication. Key emphasis is placed on understanding materials and how materials are used to make functional electronics and photonics. The primary outcome of this course is to enable students to understand the relevance of later Physics, Math, and E&P courses with real-world examples and investigations.', 'College of Engineering', ARRAY['EE   ']::TEXT[], 'Open to Electrical Engineering majors only.', NULL, ARRAY['Open to Electrical Engineering majors only']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%206'),
  ('ECE 10A', 'ECE', '10A', 'Foundations of Analog and Digital Circuits & Systems', 'FOUNDTN CIRC & SYS', 3, 'The objective of the course is to establish the foundations of analog and digital circuits. The course will introduce the student to the power of abstraction, resistive networks, network analysis, nonlinear analysis and the digital abstraction.', 'College of Engineering', ARRAY['CMPEN', 'EE   ']::TEXT[], 'Mathematics 2A-B or 3A-B or Mathematics 3AH-BH, and Mathematics 4A or 4AI or 3C, all with a minimum grade of C; and, Math 4B or 4BI or 5A with a minimum grade of C (may be taken concurrently); Physics 3, 7B or 23 (may be taken concurrently); open only to electrical engineering and computer engineering majors.', '{"t":"and","kids":[{"t":"or","kids":[{"t":"and","kids":[{"t":"course","code":"MATH 2A","concurrent":false},{"t":"course","code":"MATH 2B","concurrent":false}]},{"t":"and","kids":[{"t":"course","code":"MATH 3A","concurrent":false},{"t":"course","code":"MATH 3B","concurrent":false}]},{"t":"and","kids":[{"t":"course","code":"MATH 3AH","concurrent":false},{"t":"course","code":"MATH 3BH","concurrent":false}]}]},{"t":"or","kids":[{"t":"course","code":"MATH 4A","concurrent":false},{"t":"course","code":"MATH 4AI","concurrent":false},{"t":"course","code":"MATH 3C","concurrent":false}]},{"t":"or","kids":[{"t":"course","code":"MATH 4B","concurrent":true},{"t":"course","code":"MATH 4BI","concurrent":true},{"t":"course","code":"MATH 5A","concurrent":true}]},{"t":"or","kids":[{"t":"course","code":"PHYS 3","concurrent":true},{"t":"course","code":"PHYS 7B","concurrent":true},{"t":"course","code":"PHYS 23","concurrent":true}]}]}'::JSONB, ARRAY['open only to electrical engineering and computer engineering majors', 'all with a minimum grade of C', 'with a minimum grade of C']::TEXT[], ARRAY['Fall', 'Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%2010A'),
  ('ECE 10AL', 'ECE', '10AL', 'Foundations of Analog and Digital Circuits and Systems Lab', 'FOUNDTN CIRC LAB', 2, 'The goal of 10AL is to provide the student with a hands-on application of the concepts discussed in ECE 10A. The lab will introduce the use of microcontrollers as a data acquisition system, network analysis, resistors, nonlinear analysis and digital abstraction.', 'College of Engineering', ARRAY['CMPEN', 'EE']::TEXT[], 'ECE 10A (may be taken concurrently) with a C- or better grade.', '{"t":"course","code":"ECE 10A","concurrent":true}'::JSONB, ARRAY['with a C- or better grade']::TEXT[], ARRAY['Fall', 'Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%2010AL'),
  ('ECE 10B', 'ECE', '10B', 'Foundations of Analog and Digital Circuits and Systems', 'FOUNDTN CIRC & SYS', 3, 'The objective of the course is to introduce the MOSFET both as a simple digital switch and as controlled current source for analog design. The course will cover basic digital design, small-signal analysis, charge storage elements and operational amplifiers.', 'College of Engineering', ARRAY['CMPEN', 'EE']::TEXT[], 'ECE 10A with a C- or better grade.', '{"t":"course","code":"ECE 10A","concurrent":false}'::JSONB, ARRAY['with a C- or better grade']::TEXT[], ARRAY['Winter', 'Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%2010B'),
  ('ECE 10BL', 'ECE', '10BL', 'Foundations of Analog and Digital Circuits and Systems Lab', 'FOUNDTN CIRC LAB', 2, 'The goal of 10BL is to provide the student with a hands-on application of the concepts discussed in ECE 10B. The lab will utilize the microcontroller to introduce students to the understanding of datasheets for both digital and analog circuits, single-stage amplifier design and basic instrumentation.', 'College of Engineering', ARRAY['CMPEN', 'EE']::TEXT[], 'ECE 10B (may be taken concurrently) with a C- or better grade.', '{"t":"course","code":"ECE 10B","concurrent":true}'::JSONB, ARRAY['with a C- or better grade']::TEXT[], ARRAY['Winter', 'Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%2010BL'),
  ('ECE 10C', 'ECE', '10C', 'Foundations of Analog and Digital Circuits and Systems', 'FOUNDTN CIRC & SYS', 3, 'The objective of the course is to introduce the student to the basics of transient analysis. The course will energy and power dissipation in digital circuits, first-order and second-order linear time invariant circuits, sinusoidal steady state, impedance representation, feedback and resonance.', 'College of Engineering', ARRAY['CMPEN', 'EE']::TEXT[], 'ECE 10B with a C- or better grade.', '{"t":"course","code":"ECE 10B","concurrent":false}'::JSONB, ARRAY['with a C- or better grade']::TEXT[], ARRAY['Fall', 'Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%2010C'),
  ('ECE 10CL', 'ECE', '10CL', 'Foundations of Analog and Digital Circuits and Systems Lab', 'FOUNDTN CIRC LAB', 2, 'The goal of 10CL is to provide the student with a hands-on application of the concepts discussed in ECE 10C. The lab will utilize the microcontroller to introduce students to the understanding of propagation delay in digital circuits and the resulting power dissipation, first order linear networks, second order linear networks, sinusoidal steady-state, impedance analysis and op-amp circuits.', 'College of Engineering', ARRAY['CMPEN', 'EE']::TEXT[], 'ECE 10C (may be taken concurrently) with a C- grade or better.', '{"t":"course","code":"ECE 10C","concurrent":true}'::JSONB, ARRAY['with a C- grade or better']::TEXT[], ARRAY['Fall', 'Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%2010CL'),
  ('ECE 15A', 'ECE', '15A', 'Fundamentals of Logic Design', 'FUND OF LOGIC DES', 3, 'Boolean algebra, logic of propositions, minterm and maxterm expansions, Karnaugh maps, Quine-McCluskey method, melti-level circuits, combinational circuit design and simulation, multiplexers, decoders, programmable logic devices.', 'College of Engineering', ARRAY['EE', 'ECE', 'CMPEN', 'PRCME']::TEXT[], 'Open to electrical engineering, computer engineering, and pre-computer engineering majors only.', NULL, ARRAY['Open to electrical engineering, computer engineering, and pre-computer engineering majors only']::TEXT[], ARRAY['Fall', 'Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%2015A'),
  ('ECE 120A', 'ECE', '120A', 'Integrated Circuit Design and Fabrication', 'INTEGRATED CIRCUITS', 4, 'Theory, fabrication, and characterization of solid state devices including P-N junctions, capacitors, bipolar and MOS devices. Devices are fabricated using modern VLSI processing techniques including lithography, oxidation, diffusion, and evaporation. Physics and performance of processing steps are discussed and analyzed.', 'College of Engineering', '{}', 'ECE 132 with a minimum grade of C-.', '{"t":"course","code":"ECE 132","concurrent":false}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20120A'),
  ('ECE 120B', 'ECE', '120B', 'Integrated Circuit Design and Fabrication', 'INTEGRATED CIRCUITS', 4, 'Design, simulation, fabrication, and characterization of NMOS integrated circuits. Circuit design and layout is performed using commercial layout software. Circuits are fabricated using modern VLSI processing techniques. Circuit and discrete device electrical performance are analyzed.', 'College of Engineering', '{}', 'Either ECE 120A or ECE 124B with a minimum grade of C- or better in each of the courses.', '{"t":"or","kids":[{"t":"course","code":"ECE 120A","concurrent":false},{"t":"course","code":"ECE 124B","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20120B'),
  ('ECE 122A', 'ECE', '122A', 'VLSI Principles', 'VLSI PRINCIPLES', 4, 'Introduction to CMOS digital VLSI design: CMOS devices and manufacturing technology; transistor level design of static and dynamic logic gates and components and interconnections; circuit characterization: delay, noise margins, and power dissipation; combinational and sequential circuits; arithmetic operations and memories.', 'College of Engineering', '{}', 'ECE 152A with a minimum grade of C-.', '{"t":"course","code":"ECE 152A","concurrent":false}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Fall']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20122A'),
  ('ECE 122B', 'ECE', '122B', 'VLSI Architecture and Design', 'VLSI ARCH/DESIGN', 4, 'Practical issues in VLSI circuit design, pad/pin limitations, clocking and interfacing standards, electrical packaging for high-speed and high-performance design. On-chip noise and crosstalk, clock and power distribution, architectural and circuit design constraints, interconnection limits and transmission line effects.', 'College of Engineering', '{}', 'ECE 124A or ECE 123 or ECE 122A with a minimum grade of C-.', '{"t":"or","kids":[{"t":"course","code":"ECE 124A","concurrent":false},{"t":"course","code":"ECE 123","concurrent":false},{"t":"course","code":"ECE 122A","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20122B'),
  ('ECE 123', 'ECE', '123', 'High-Performance Digital Circuit Design', 'HI PERF DIG CIR DES', 4, 'Introduction to high-performance digital circuit design techniques. Basics of device physics including deep submicron effects; device sizing and logical effort; Circuit design styles; clocking & timing issues; memory & datapath design; Low-power design; VLSI design flows and associated EDA tools.', 'College of Engineering', ARRAY['EE', 'CMPEN']::TEXT[], 'ECE 10A-B-C and ECE 10AL-10BL-10CL or ECE 2A-B-C with a minimum grade of C- in each of those courses; open to both electrical engineering and computer engineering majors only.', '{"t":"and","kids":[{"t":"course","code":"ECE 10A","concurrent":false},{"t":"course","code":"ECE 10B","concurrent":false},{"t":"course","code":"ECE 10C","concurrent":false},{"t":"or","kids":[{"t":"and","kids":[{"t":"course","code":"ECE 10AL","concurrent":false},{"t":"course","code":"ECE 10BL","concurrent":false},{"t":"course","code":"ECE 10CL","concurrent":false}]},{"t":"and","kids":[{"t":"course","code":"ECE 2A","concurrent":false},{"t":"course","code":"ECE 2B","concurrent":false},{"t":"course","code":"ECE 2C","concurrent":false}]}]}]}'::JSONB, ARRAY['open to both electrical engineering and computer engineering majors only', 'with a minimum grade of C-']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20123'),
  ('ECE 125', 'ECE', '125', 'High Speed Digital Integrated Circuit Design', 'HI SPEED IC DESIGN', 4, 'Advanced digital VLSI design: CMOS scaling, nanoscale issues including variability, thermal management, interconnects, reliability; non-clocked, clocked and self-timed logic gates; clocked storage elements; high-speed components, PLLs and DLLs; clock and power distribution; memory systems; signaling and I/O design; low-power design.', 'College of Engineering', '{}', 'ECE 124A or 137A with a minimum grade of C- (in either).', '{"t":"or","kids":[{"t":"course","code":"ECE 124A","concurrent":false},{"t":"course","code":"ECE 137A","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C-', '(in either)']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20125'),
  ('ECE 130A', 'ECE', '130A', 'Signal Analysis and Processing', 'SIGNAL ANALYSIS', 4, 'Analysis of continuous time linear systems in the time and frequency domains. Superposition and convolution. Bilateral and unilateral Laplace transforms. Fourier series and Fourier transforms. Filtering, modulation, and feedback.', 'College of Engineering', ARRAY['EE', 'CMPEN']::TEXT[], 'Mathematics 4B or 5A with a minimum of grade of C; open to EE and computer engineering majors only.', '{"t":"or","kids":[{"t":"course","code":"MATH 4B","concurrent":false},{"t":"course","code":"MATH 5A","concurrent":false}]}'::JSONB, ARRAY['open to EE and computer engineering majors only', 'with a minimum of grade of C']::TEXT[], ARRAY['Fall', 'Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20130A'),
  ('ECE 130B', 'ECE', '130B', 'Signal Analysis and Processing', 'SIGNAL ANALYSIS', 4, 'Analysis of discrete time linear systems in the time and frequency domains. Z transforms, Discrete Fourier transforms. Sampling and aliasing.', 'College of Engineering', ARRAY['EE', 'CMPEN']::TEXT[], 'ECE 130A with a minimum grade of C- or better; open to EE and computer engineering majors only.', '{"t":"course","code":"ECE 130A","concurrent":false}'::JSONB, ARRAY['open to EE and computer engineering majors only', 'with a minimum grade of C-']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20130B'),
  ('ECE 130C', 'ECE', '130C', 'Introduction to Applied Linear Algebra', 'INTRO APP LIN ALG', 4, 'Introduction to applied linear algebra: matrix arithmetic, vector spaces, orthogonality, matrix factorizations, determinants, eigenvalues and eigenvectors, difference and differential equations.', 'College of Engineering', ARRAY['EE', 'CMPEN']::TEXT[], 'Math 4B or Math 5A recommended. Open to EE and CE majors only.', NULL, ARRAY['Open to EE and CE majors only', 'recommended', '[curated] Catalog says MATH 4B / 5A are ''recommended'', not required.']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20130C'),
  ('ECE 132', 'ECE', '132', 'Introduction to Solid-State Electronic Devices', 'INTRO ELEC DEVICE', 4, 'Electrons and holes in semiconductors; doping (P and N); state occupation statistics, transport properties of electrons and holes; P-N junction diodes; I-V, C-V, and switching properties of P-N junctions; introduction of bipolar transitors, MOSFET''s and JFET''s.', 'College of Engineering', ARRAY['CMPEN', 'EE   ']::TEXT[], 'Physics 4 or 24 or 7D with a minimum grade of C-; Mathematics 4B, 4BI or 5A with a minimum grade of C; open to EE and computer engineering majors only.', '{"t":"and","kids":[{"t":"or","kids":[{"t":"course","code":"PHYS 4","concurrent":false},{"t":"course","code":"PHYS 24","concurrent":false},{"t":"course","code":"PHYS 7D","concurrent":false}]},{"t":"or","kids":[{"t":"course","code":"MATH 4B","concurrent":false},{"t":"course","code":"MATH 4BI","concurrent":false},{"t":"course","code":"MATH 5A","concurrent":false}]}]}'::JSONB, ARRAY['open to EE and computer engineering majors only', 'with a minimum grade of C-', 'with a minimum grade of C']::TEXT[], ARRAY['Fall']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20132'),
  ('ECE 133', 'ECE', '133', 'Introduction to Optimization and Learning', 'INTRO OPT AND LEARN', 4, 'Includes an undergraduate level introduction to the theory of optimization, along with relevant applications of optimization in machine learning and statistics, signal processing, decision making and control.', 'College of Engineering', ARRAY['CMPEN', 'EE']::TEXT[], 'Upper division standing Electrical Engineering and Computer Engineering majors only.', NULL, ARRAY['Upper division standing Electrical Engineering and Computer Engineering majors only']::TEXT[], ARRAY['Fall']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20133'),
  ('ECE 134', 'ECE', '134', 'Introduction to Fields and Waves', 'INTR FIELDS & WAVES', 4, 'Introduction to applied electromagnetics and wave phenomena in high frequency electron circuits and systems. Waves on transmission-lines, elements of electrostatics and magnetostatics and applications, plane waves, examples and applications to RF, microwave, and optical systems.', 'College of Engineering', ARRAY['CMPEN', 'EE   ']::TEXT[], 'Physics 3 or 23 or 7B and Physics 4 or 24 or PHYS 7C with a minimum grade of C-; Mathematics 4B or 4BI or 5A and Mathematics 5B or 6A or 6AI with a minimum grade of C in each; and Mathematics 5C or 6B with a minimum grade of C-; open to EE and computer engineering majors only.', '{"t":"and","kids":[{"t":"or","kids":[{"t":"course","code":"PHYS 3","concurrent":false},{"t":"course","code":"PHYS 23","concurrent":false},{"t":"course","code":"PHYS 7B","concurrent":false}]},{"t":"or","kids":[{"t":"course","code":"PHYS 4","concurrent":false},{"t":"course","code":"PHYS 24","concurrent":false},{"t":"course","code":"PHYS 7C","concurrent":false}]},{"t":"or","kids":[{"t":"course","code":"MATH 4B","concurrent":false},{"t":"course","code":"MATH 4BI","concurrent":false},{"t":"course","code":"MATH 5A","concurrent":false}]},{"t":"or","kids":[{"t":"course","code":"MATH 5B","concurrent":false},{"t":"course","code":"MATH 6A","concurrent":false},{"t":"course","code":"MATH 6AI","concurrent":false}]},{"t":"or","kids":[{"t":"course","code":"MATH 5C","concurrent":false},{"t":"course","code":"MATH 6B","concurrent":false}]}]}'::JSONB, ARRAY['open to EE and computer engineering majors only', 'with a minimum grade of C-', 'with a minimum grade of C', 'with a minimum grade of C-']::TEXT[], ARRAY['Fall']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20134'),
  ('ECE 135', 'ECE', '135', 'Optical Fiber Communications', 'OPT FIBER COMM', 4, 'Optical fiber as a transmission medium, dispersion and nonlinear effects in fiber transmission, fiber and semiconductor optical amplifiers and lasers, optical modulators, photo detectors, optical receivers, wavelength division multiplexing components, optical filters, basic transmission system analysis and design.', 'College of Engineering', '{}', 'ECE 132 and 134 with a minimum grade of C- in both.', '{"t":"and","kids":[{"t":"course","code":"ECE 132","concurrent":false},{"t":"course","code":"ECE 134","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20135'),
  ('ECE 136A', 'ECE', '136A', 'Introduction to Optics and Photonics', 'INTRO TO OPT & PHOT', 4, 'Fundamentals of optical and photonics including lens theory, basics of imaging, microscopes and telescopes, 2-dimensional Fourier Transforms, optical coherence, interferometry, lasers, laser phase noise and laser linewidth.', 'College of Engineering', ARRAY['CMPEN', 'EE   ']::TEXT[], 'PHYS 5/PHYS 5L or PHYS 7D/PHYS 7L or PHYS 25 or equivalent.', '{"t":"or","kids":[{"t":"and","kids":[{"t":"course","code":"PHYS 5","concurrent":false},{"t":"course","code":"PHYS 5L","concurrent":false}]},{"t":"and","kids":[{"t":"course","code":"PHYS 7D","concurrent":false},{"t":"course","code":"PHYS 7L","concurrent":false}]},{"t":"course","code":"PHYS 25","concurrent":false}]}'::JSONB, ARRAY['or equivalent']::TEXT[], ARRAY['Fall']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20136A'),
  ('ECE 136B', 'ECE', '136B', 'Optics and Imaging', 'OPTICS & IMAGING', 4, 'Photonics, with an emphasis on imaging: optical design (Zemax), ray transfer matrices, aberrations, scattering, resolution and optical transfer functions, adaptive optics, polarization, laser scanning, ultrafast pulses, detectors, superresolution, and VR/AR.', 'College of Engineering', ARRAY['CMPEN', 'EE   ']::TEXT[], 'PHYS 5/PHYS 5L or PHYS 7D/PHYS 7L or PHYS 25 or equivalent.', '{"t":"or","kids":[{"t":"and","kids":[{"t":"course","code":"PHYS 5","concurrent":false},{"t":"course","code":"PHYS 5L","concurrent":false}]},{"t":"and","kids":[{"t":"course","code":"PHYS 7D","concurrent":false},{"t":"course","code":"PHYS 7L","concurrent":false}]},{"t":"course","code":"PHYS 25","concurrent":false}]}'::JSONB, ARRAY['or equivalent']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20136B'),
  ('ECE 136C', 'ECE', '136C', 'Quantum Photonics', 'QUANTUM PHOTONICS', 4, 'Introduction to quantum information, fundamentals of quantum photonics, quantum light generation and detection, quantum coherence and superposition, wave-particle duality, qubits, quantum logic, entanglement, quantum measurement.', 'College of Engineering', ARRAY['CMPEN', 'EE   ']::TEXT[], 'PHYS 5/PHYS 5L or PHYS 7D/PHYS 7L or PHYS 25 or equivalent.', '{"t":"or","kids":[{"t":"and","kids":[{"t":"course","code":"PHYS 5","concurrent":false},{"t":"course","code":"PHYS 5L","concurrent":false}]},{"t":"and","kids":[{"t":"course","code":"PHYS 7D","concurrent":false},{"t":"course","code":"PHYS 7L","concurrent":false}]},{"t":"course","code":"PHYS 25","concurrent":false}]}'::JSONB, ARRAY['or equivalent']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20136C'),
  ('ECE 137A', 'ECE', '137A', 'Circuits and Electronics I', 'CIRCUIT & ELECTR I', 4, 'Analysis and design of single stage and multistage transistor circuits including biasing, gain, impedances and maximum signal levels.', 'College of Engineering', ARRAY['EE', 'ECE']::TEXT[], 'ECE 10A-B-C and 10AL-BL-CL or 2A-B-C, 130A and 132 all with a minimum grade of C-; open to EE majors only.', '{"t":"and","kids":[{"t":"course","code":"ECE 10A","concurrent":false},{"t":"course","code":"ECE 10B","concurrent":false},{"t":"course","code":"ECE 10C","concurrent":false},{"t":"or","kids":[{"t":"and","kids":[{"t":"course","code":"ECE 10AL","concurrent":false},{"t":"course","code":"ECE 10BL","concurrent":false},{"t":"course","code":"ECE 10CL","concurrent":false}]},{"t":"and","kids":[{"t":"course","code":"ECE 2A","concurrent":false},{"t":"course","code":"ECE 2B","concurrent":false},{"t":"course","code":"ECE 2C","concurrent":false}]}]},{"t":"course","code":"ECE 130A","concurrent":false},{"t":"course","code":"ECE 132","concurrent":false}]}'::JSONB, ARRAY['open to EE majors only', 'all with a minimum grade of C-']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20137A'),
  ('ECE 137B', 'ECE', '137B', 'Circuits and Electronics II', 'CIRCUIT & ELECTR II', 4, 'Analysis and design of single stage and multistage transistor circuits at low and high frequencies. Transient response. Analysis and design of feedback circuits. Stability criteria.', 'College of Engineering', ARRAY['ECE', 'EE']::TEXT[], 'ECE 10C and 10CL or 2C, and ECE 137A with a minimum grade of C- in all; open to EE majors only.', '{"t":"and","kids":[{"t":"course","code":"ECE 10C","concurrent":false},{"t":"or","kids":[{"t":"course","code":"ECE 10CL","concurrent":false},{"t":"course","code":"ECE 2C","concurrent":false}]},{"t":"course","code":"ECE 137A","concurrent":false}]}'::JSONB, ARRAY['open to EE majors only', 'with a minimum grade of C-']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20137B'),
  ('ECE 139', 'ECE', '139', 'Probability and Statistics', 'PROB & STAT', 4, 'Fundamentals of probability, conditional probability, Bayes rule, random variables, functions of random variables, expectation and high-order moments, Markov chains, hypothesis testing.', 'College of Engineering', ARRAY['ECE', 'CMPEN', 'EE', 'PRCME']::TEXT[], 'Open to Electrical Engineering, Computer Engineering and pre-Computer Engineering majors only.', NULL, ARRAY['Open to Electrical Engineering, Computer Engineering and pre-Computer Engineering majors only']::TEXT[], ARRAY['Fall', 'Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20139'),
  ('ECE 141A', 'ECE', '141A', 'Introduction to Nanoelectromechanical and Microelectromechanical systems (NEMS/MEMS)', 'INTRO TO NEMS/MEMS', 3, 'Introduction to nano- and microtechnology. Scaling laws and nanoscale physics are stressed. Individual subjects at the nanoscale including materials, mechanics, photonics, electronics, and fluidics will be described, with an emphasis on differences of behavior at the nanoscale and real-world examples.', 'College of Engineering', '{}', 'ME 16 or ME W 16 and 17; ME 152A and ME 151A (may be concurrent); or ECE 130A & 137A with a minimum grade of C- in both.', '{"t":"or","kids":[{"t":"and","kids":[{"t":"course","code":"ME 16","concurrent":false},{"t":"course","code":"ME 17","concurrent":false},{"t":"course","code":"ME 152A","concurrent":false},{"t":"course","code":"ME 151A","concurrent":true}]},{"t":"and","kids":[{"t":"course","code":"ECE 130A","concurrent":false},{"t":"course","code":"ECE 137A","concurrent":false}]}]}'::JSONB, ARRAY['with a minimum grade of C-', '[curated] Trailing ''; or ECE 130A & 137A'' makes the whole ME sequence an alternative to the ECE pair; parser split it into a top-level AND.']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20141A'),
  ('ECE 141B', 'ECE', '141B', 'MEMS: Processing and Device Characterization', 'MEMS: SEMICOND PROC', 4, 'Lectures and laboratory on semiconductor-based processing for MEMS. Description of key equipment and characterization tools used for MEMS and design, fabrication, characterization and testing of MEMS Emphasis on current MEMS devices including accelerometers, comb drives, micro-reactors and capacitor-actuators.', 'College of Engineering', '{}', 'ME 141A, ME 163 (may be concurrent); or ECE 141A.', '{"t":"or","kids":[{"t":"and","kids":[{"t":"course","code":"ME 141A","concurrent":false},{"t":"course","code":"ME 163","concurrent":true}]},{"t":"course","code":"ECE 141A","concurrent":false}]}'::JSONB, '{}', ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20141B'),
  ('ECE 141C', 'ECE', '141C', 'Introduction to Microfluidics and BioMEMS', 'INTRO MICROFLUIDS', 3, 'Introduces physical phenomena associated with microsale/nanoscale fluid mechanics, microfluids, and bioMEMS. Analytical methods and numerical simulation tools are used for analysis of microfluids.', 'College of Engineering', ARRAY['ME', 'EE']::TEXT[], 'ME 141A or ECE 141A; open to ME and EE majors only.', '{"t":"or","kids":[{"t":"course","code":"ME 141A","concurrent":false},{"t":"course","code":"ECE 141A","concurrent":false}]}'::JSONB, ARRAY['open to ME and EE majors only']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20141C'),
  ('ECE 142', 'ECE', '142', 'INTRODUCTION TO POWER ELECTRONICS', 'INTRO TO POWER ELEC', 4, 'An introduction to modern switched-mode power electronics and associated devices. Covers modern converter/inverter topologies for the control and conversion of electrical power with high efficiency with applications in power supplies, renewable energy systems, lighting, electric/hybrid vehicles, and motor drivers.', 'College of Engineering', ARRAY['EE']::TEXT[], 'ECE 132, ECE 134 and ECE 137A with a minimum grade of C- in all; open to EE majors only.', '{"t":"and","kids":[{"t":"course","code":"ECE 132","concurrent":false},{"t":"course","code":"ECE 134","concurrent":false},{"t":"course","code":"ECE 137A","concurrent":false}]}'::JSONB, ARRAY['open to EE majors only', 'with a minimum grade of C-']::TEXT[], ARRAY['Winter', 'Spring']::TEXT[], 'uncertain', ARRAY['ECE department grid lists Winter 2026-27 as TBA']::TEXT[], 'ECE Undergraduate Courses 2026-27 grid + Schedule of Classes history', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20142'),
  ('ECE 144', 'ECE', '144', 'Electromagnetic Fields and Waves', 'ELECTRO FLD & WAVES', 4, 'Waves on transmission lines, Maxwell''s equations, skin effect, propagation and reflection of electromagnetic waves, microwave integrated circuit principles, metal and dielectric waveguides, resonant cavities, antennas. Microwave and optical device examples and experiencewith modern microwave and CAD software.', 'College of Engineering', '{}', 'ECE 134 with a minimum grade of C-.', '{"t":"course","code":"ECE 134","concurrent":false}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20144'),
  ('ECE 145A', 'ECE', '145A', 'Communication Electronics', 'COMM ELECTRONICS', 5, 'RF/Microwave circuits. Transistor, transmission-line, and passive element characteristics. Transmission-line theory and impedance matching. Amplifier design for maximum available gain. Amplifier stability. Gain compression and power limits. Introduction to noise figure, and to intermodulation distortion.', 'College of Engineering', '{}', 'ECE 137A-B with a minimum grade of C- in both.', '{"t":"and","kids":[{"t":"course","code":"ECE 137A","concurrent":false},{"t":"course","code":"ECE 137B","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Fall']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20145A'),
  ('ECE 145B', 'ECE', '145B', 'Communication Electronics II', 'COMM ELECTRONICS II', 5, 'RF models for CMOS and BJT. Discrete vs. IC implementation. On-chip passive components. LNAs. PAs. T/R switches. Mixers. VCOs. Poly-phase filters Radio link budget. Analog and digital modulation schemes. Introduction to receiver architectures. I&Q modulation. Image-reject architectures.', 'College of Engineering', ARRAY['EE', 'ECE']::TEXT[], 'ECE 145A with a minimum grade of C-; EE majors only.', '{"t":"course","code":"ECE 145A","concurrent":false}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20145B'),
  ('ECE 145C', 'ECE', '145C', 'Communication Electronics III', 'COMM ELECTRONIC III', 5, 'Modern wireless communication standards. Cellular phone. Wireless LAN. Introduction to multi-access techniques. Advanced modulation schemes. Interference and distortion. Modern transceiver architectures. Direct conversion vs. low IF vs. super-heterodyne. Sub-sampling receiver. Direct polar modulator. Frequency synthesis using PLL.', 'College of Engineering', '{}', 'ECE 145B with a minimum grade of C-.', '{"t":"course","code":"ECE 145B","concurrent":false}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20145C'),
  ('ECE 146A', 'ECE', '146A', 'Digital Communication Fundamentals', 'DIG COMM FUND', 5, 'Signal and channel models, with emphasis on wireless systems; digital modulation; demodulation basics; statistical modeling of noise, including review of probability theory and random variables.', 'College of Engineering', ARRAY['EE', 'ECE', 'CMPEN']::TEXT[], 'ECE 130A-B with a minimum grade of C-; ECE 139 or PSTAT 120A; open to CE & EE majors only.', '{"t":"and","kids":[{"t":"course","code":"ECE 130A","concurrent":false},{"t":"course","code":"ECE 130B","concurrent":false},{"t":"or","kids":[{"t":"course","code":"ECE 139","concurrent":false},{"t":"course","code":"PSTAT 120A","concurrent":false}]}]}'::JSONB, ARRAY['open to CE & EE majors only', 'with a minimum grade of C-']::TEXT[], ARRAY['Fall']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20146A'),
  ('ECE 146B', 'ECE', '146B', 'Wireless Communication Systems Design', 'WIRLS  COM SYS DES', 5, 'Optimal demodulation, including signal space geometry; communication performance characterization; advanced wireless communication techniques, including multi-antenna and multicarrier systems; other emerging frontiers in communications.', 'College of Engineering', ARRAY['EE', 'ECE', 'CMPEN']::TEXT[], 'ECE 130A-B and 146A with minimum grades of C-; ECE 139 or PSTAT 120A; open to CE and EE majors only.', '{"t":"and","kids":[{"t":"course","code":"ECE 130A","concurrent":false},{"t":"course","code":"ECE 130B","concurrent":false},{"t":"course","code":"ECE 146A","concurrent":false},{"t":"or","kids":[{"t":"course","code":"ECE 139","concurrent":false},{"t":"course","code":"PSTAT 120A","concurrent":false}]}]}'::JSONB, ARRAY['open to CE and EE majors only', 'with minimum grades of C-']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20146B'),
  ('ECE 147A', 'ECE', '147A', 'Feedback Control Systems - Theory and Design', 'CONTROL SYSTEMS', 5, 'Feedback systems design, specifications in time and frequency domains. Analysis and synthesis of closed loope systems. Computer aided analysis anddesign.', 'College of Engineering', ARRAY['EE', 'CMPEN', 'ECE']::TEXT[], 'ECE 130A-B with a minimum grade of C- in each; open to electrical engineering and computer engineering majors only.', '{"t":"and","kids":[{"t":"course","code":"ECE 130A","concurrent":false},{"t":"course","code":"ECE 130B","concurrent":false}]}'::JSONB, ARRAY['open to electrical engineering and computer engineering majors only', 'with a minimum grade of C-']::TEXT[], ARRAY['Fall']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20147A'),
  ('ECE 147B', 'ECE', '147B', 'Digital Control Systems - Theory and Design', 'DIGITAL CONTROL', 5, 'Analysis of sampled data feedback systems; state space description of linear systems: observability, controllability, pole assignment, state feedback, observers. Design of digital control systems.', 'College of Engineering', ARRAY['EE', 'CMPEN', 'ECE']::TEXT[], 'ECE 147A with a minimum grade of C-; open to EE and CE majors only.', '{"t":"course","code":"ECE 147A","concurrent":false}'::JSONB, ARRAY['open to EE and CE majors only', 'with a minimum grade of C-']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20147B'),
  ('ECE 147C', 'ECE', '147C', 'Control System Design Project', 'CONTROL SYS PROJ', 5, 'Students are required to design, implement, and document a significant control systems project. The project is implemented in hardware or in high-fidelity numerical simulators. Lectures and laboratories cover special topics related to the practical implementation of control systems.', 'College of Engineering', '{}', 'ECE 147A or ME 155B or ME 173 with a minimum grade of C-.', '{"t":"or","kids":[{"t":"course","code":"ECE 147A","concurrent":false},{"t":"course","code":"ME 155B","concurrent":false},{"t":"course","code":"ME 173","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20147C'),
  ('ECE 148', 'ECE', '148', 'Applications of Signal Analysis and Processing', 'SIGNAL ANALYSIS', 4, 'A sequence of engineering applications of signal analysis and processing techniques; in communications, image processing, analog and digital filter design, signal detection and parameter estimation, holography and tomography, Fourier optics, and microwave and acoustic sensing.', 'College of Engineering', '{}', 'ECE 130A and 130B with a minimum grade of C- in both.', '{"t":"and","kids":[{"t":"course","code":"ECE 130A","concurrent":false},{"t":"course","code":"ECE 130B","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20148'),
  ('ECE 149', 'ECE', '149', 'Game Theory for Networked Systems', 'GAME THEORY', 4, 'An overview of game theory with an emphasis on application to multiagent systems. Game theory focuses on the study of systems that are comprised of interacting and possibly competing decision-making entities. Examples drawn from engineered, economics, and social systems.', 'College of Engineering', '{}', 'UPPER DIVISION STANDING OR CONSENT OF INSTRUCTOR.', NULL, ARRAY['UPPER DIVISION STANDING OR CONSENT OF INSTRUCTOR']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20149'),
  ('ECE 150', 'ECE', '150', 'MOBILE EMBEDDED SYSTEMS', 'MOBILE EMBED SYSTEM', 4, 'Architectures of modern smartphones and their key hardware components including mobile application processors, communications chips, display, touchscreen, graphics, camera, battery, GPS,and various sensors; the OS and software development platform of smartphones; smartphone applications; low power design techniques.', 'College of Engineering', '{}', 'Proficiency in JAVA programming, and a C- in ECE 152A.', '{"t":"course","code":"ECE 152A","concurrent":false}'::JSONB, ARRAY['Proficiency in JAVA programming, and a C- in ECE 152A', '[curated] Course reference sits inside a grade clause (''a C- in ECE 152A''), which the grade-clause stripper removed.']::TEXT[], '{}', 'uncertain', ARRAY['ECE department grid marks Spring 2026-27 as not offered']::TEXT[], 'ECE Undergraduate Courses 2026-27 grid + Schedule of Classes history', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20150'),
  ('ECE 152A', 'ECE', '152A', 'Digital Design Principles', 'DIGITAL DESIN PRIN.', 5, 'Design of synchronous digital systems: timing diagrams, propagation delay, latches and flip-flops, shift registers and counters, Mealy/Moore finite state machines, Verilog, 2-phase clocking, timing analysis, CMOS implementation, S-RAM, RAM-based designs, ASM charts, state minimization.', 'College of Engineering', ARRAY['CMPSC', 'CPSCI', 'EE', 'ECE', 'CMPEN']::TEXT[], 'ECE 15A and ECE 2A or ECE 10A & ECE 10AL with a minimum grade of C- in each course; or Computer Science 30 or 64 with a minimum grade of C- in each course; open to electrical engineering, computer engineering, and computer science majors only.', '{"t":"or","kids":[{"t":"and","kids":[{"t":"course","code":"ECE 15A","concurrent":false},{"t":"or","kids":[{"t":"course","code":"ECE 2A","concurrent":false},{"t":"and","kids":[{"t":"course","code":"ECE 10A","concurrent":false},{"t":"course","code":"ECE 10AL","concurrent":false}]}]}]},{"t":"course","code":"CMPSC 30","concurrent":false},{"t":"course","code":"CMPSC 64","concurrent":false}]}'::JSONB, ARRAY['open to electrical engineering, computer engineering, and computer science majors only', 'with a minimum grade of C-', 'with a minimum grade of C-', '[curated] ''&'' binds tighter than ''or'' here: ECE 10A & ECE 10AL is one alternative to the retired ECE 2A.']::TEXT[], ARRAY['Winter', 'Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20152A'),
  ('ECE 152B', 'ECE', '152B', 'Digital Design Methodologies', 'DIGITAL DESIGN METH', 5, 'Design methodologies of digital systems, the register and processor levels. Design of functional subsystems, including arithmetic processors, hardwired and microprogrammed control units, memory systems, and bussing systems. System organization including communication, input/output systems, and multiple CPU systems.', 'College of Engineering', ARRAY['CMPEN', 'EE   ', 'CMPSC']::TEXT[], 'ECE 152A with a minimum grade of C-; open to EE, CMPEN, and Computer Science majors only.', '{"t":"course","code":"ECE 152A","concurrent":false}'::JSONB, ARRAY['open to EE, CMPEN, and Computer Science majors only', 'with a minimum grade of C-']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20152B'),
  ('ECE 153A', 'ECE', '153A', 'Hardware/Software Interface', 'HRDW/SFTW INTERFACE', 4, 'Design and coding of embedded programs. Real-time constraints and management of resources. Practical I/O interfaces and protocols, polling, interrupt maintenance, atomic code, blocking and non-blocking tasks. Static and dynamic task scheduling under real-time and limited resource constraints.', 'College of Engineering', ARRAY['CMPSC', 'EE', 'CMPEN']::TEXT[], 'Upper division standing in Computer Engineering, Computer Science and Electrical Engineering. Familiarity with C, FiniteAutomata, and Computer Architecture.', NULL, ARRAY['Upper division standing in Computer Engineering, Computer Science and Electrical Engineering', 'Familiarity with C, FiniteAutomata, and Computer Architecture']::TEXT[], ARRAY['Fall']::TEXT[], 'uncertain', ARRAY['ECE department grid marks Fall 2026-27 as not offered']::TEXT[], 'ECE Undergraduate Courses 2026-27 grid + Schedule of Classes history', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20153A'),
  ('ECE 153B', 'ECE', '153B', 'Sensor and Peripheral Interface Design', 'SNSR/PERPH INT DSGN', 4, 'Hardware description languages; field-programmable logic and ASIC design techniques. Mixed-signal techniques: A/D and D/A converter interfaces; video and audio signal acquisition, processing and generation, communication and network interfaces.', 'College of Engineering', '{}', 'ECE 152A with a minimum grade of C-.', '{"t":"course","code":"ECE 152A","concurrent":false}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Fall', 'Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20153B'),
  ('ECE 154A', 'ECE', '154A', 'Introduction to Computer Architecture', 'INTRO COMPUTER ARCH', 4, 'Instruction-set architecture (ISA) and computer performance; Machine instructions, assembly, addressing modes; Memory map,arrays, pointers; Procedure calls; Number formats; Simple ALUs; Data path,control, microprogram; Buses, I/O programming, interrupts; Pipelined data paths and control schemes.', 'College of Engineering', ARRAY['EE', 'CMPEN', 'ECE']::TEXT[], 'ECE 152A with a minimum grade of C-; open to EE and CMPEN majors only.', '{"t":"course","code":"ECE 152A","concurrent":false}'::JSONB, ARRAY['open to EE and CMPEN majors only', 'with a minimum grade of C-']::TEXT[], ARRAY['Fall']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20154A'),
  ('ECE 154B', 'ECE', '154B', 'Advanced Computer Architecture', 'ADV COMP ARCH', 4, 'ISA variations; Pipeline data and controlhazards; Fast ALU design; Instruction-level parallelism, multithreading, VLIW; Vector and array processing, multi/many-core chips; Cache and virtual memory; Disk arrays; Shared- and distributed-memory systems, supercomputers; Reconfigurable and application-specific circuits.', 'College of Engineering', ARRAY['EE', 'CMPEN', 'ECE']::TEXT[], 'ECE 154A with a C- grade or better. Open to EE and CMPEN majors only.', '{"t":"course","code":"ECE 154A","concurrent":false}'::JSONB, ARRAY['Open to EE and CMPEN majors only', 'with a C- grade or better']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20154B'),
  ('ECE 157A', 'ECE', '157A', 'Machine Learning in Design and Test Automation', 'MACH LEARN DES TEST', 4, 'Introduces the various machine learning techniques and how they are utilized to improve hardware design and test automation processes. The potential benefits and theoretical barriers for implementing a machine learning solution in practice are explained.', 'College of Engineering', ARRAY['CMPEN', 'EE']::TEXT[], 'ECE 152A with a minimum grade of C-.', '{"t":"course","code":"ECE 152A","concurrent":false}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Fall']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20157A'),
  ('ECE 157B', 'ECE', '157B', 'Artificial Intelligence in Design and Test Automation', 'ART INTEL DES TEST', 4, 'Introduces an artificial intelligence system view to apply machine learning in design and test automation processes. The various components for building an Intelligent Engineering Assistant (IEA) to perform an engineering task in an industrial setting are explained.', 'College of Engineering', ARRAY['CMPEN', 'EE']::TEXT[], 'ECE 157A with a minimum grade of C-.', '{"t":"course","code":"ECE 157A","concurrent":false}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20157B'),
  ('ECE 157C', 'ECE', '157C', 'Principles of Verification and Test', 'Verif and Test', 4, 'Covers theories and practices of verification/test for checking hardware correctness and trustworthiness of large language models. A connection between the two is drawn. Students learn the principles of verification and test and how to apply them in both contexts.', 'College of Engineering', ARRAY['CMPEN', 'EE   ']::TEXT[], 'Upper-division standing; open to Computer Engineering and Electrical Engineering Majors.', NULL, ARRAY['open to Computer Engineering and Electrical Engineering Majors', 'Upper-division standing']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20157C'),
  ('ECE 158', 'ECE', '158', 'Digital Signal Processing', 'DIGITAL SIGNAL PROC', 4, 'Digital Signal Processing, with Applications: The Fast Fourier transform, discrete cosine transform, and multirate digital signal processing techniques, with applications to digital cellular communications and wireless access points, and audio, voice, still image, video, and biological signal analysis, recognition and compression.', 'College of Engineering', ARRAY['EE', 'ECE']::TEXT[], 'ECE 130A-B with a minimum grade of C-; open to EE majors only.', '{"t":"and","kids":[{"t":"course","code":"ECE 130A","concurrent":false},{"t":"course","code":"ECE 130B","concurrent":false}]}'::JSONB, ARRAY['open to EE majors only', 'with a minimum grade of C-']::TEXT[], ARRAY['Spring']::TEXT[], 'uncertain', ARRAY['ECE department grid marks Spring 2026-27 as not offered']::TEXT[], 'ECE Undergraduate Courses 2026-27 grid + Schedule of Classes history', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20158'),
  ('ECE 160', 'ECE', '160', 'Multimedia Systems', 'MULTIMEDIA SYSTEMS', 4, 'Introduction to multimedia and applications, including WWW, image/video databases and video streaming. Covers media content analysis, media data organization and indexing (image/video databases), and media data distribution and interaction (video on-demand and interactive TV).', 'College of Engineering', ARRAY['ECE', 'CMPEN', 'CPSCI', 'CMPSC', 'CRTST', 'EE']::TEXT[], 'Upper-division standing; open to electrical engineering, computer engineering, computer science, and creative studies majors only.', NULL, ARRAY['open to electrical engineering, computer engineering, computer science, and creative studies majors only', 'Upper-division standing']::TEXT[], '{}', 'uncertain', ARRAY['ECE department grid marks Spring 2026-27 as not offered']::TEXT[], 'ECE Undergraduate Courses 2026-27 grid + Schedule of Classes history', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20160'),
  ('ECE 162A', 'ECE', '162A', 'The Quantum Description of Electronic Materials', 'QUANTUM ELEC MATRLS', 4, 'Electrons as particles and waves, Schrodinger''s equation and illustrative solutions. Tunnelling. Atomic structure, the exclusion principle and the periodic table. Bonds. Free electrons in metals, periodic potentials and energy bands.', 'College of Engineering', ARRAY['ECE', 'MATRL', 'EE']::TEXT[], 'ECE 130A-B and 134 with a minimum grade of C- in all; open to EE, seniors in the BS/MS program and Materials graduate students only.', '{"t":"and","kids":[{"t":"course","code":"ECE 130A","concurrent":false},{"t":"course","code":"ECE 130B","concurrent":false},{"t":"course","code":"ECE 134","concurrent":false}]}'::JSONB, ARRAY['open to EE, seniors in the BS/MS program and Materials graduate students only', 'with a minimum grade of C-']::TEXT[], ARRAY['Fall']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20162A'),
  ('ECE 162B', 'ECE', '162B', 'Fundamentals of the Solid State', 'FUND SOLID STATE', 4, 'Crystal lattices and the structure of solids, with emphasis on semiconductors. Lattice vibrations. Electronic states and energy bands. Electrical and thermal conduction. Dielectric and optical properties. Semiconductor devices: diffusion, P-N junctions and diode behavior.', 'College of Engineering', ARRAY['EE', 'MATRL', 'ECE']::TEXT[], 'ECE 162A with a minimum grade of C-; open to EE, senior students in the BS/MS programs and Materials graduate students only.', '{"t":"course","code":"ECE 162A","concurrent":false}'::JSONB, ARRAY['open to EE, senior students in the BS/MS programs and Materials graduate students only', 'with a minimum grade of C-']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20162B'),
  ('ECE 162C', 'ECE', '162C', 'Optoelectronic Materials and Devices', 'OPTOEL MAT & DEV', 4, 'Optical transitions in solids. Direct and indirect gap semiconductors. Luminescence. Excitons and photons. Fundamentals of optoelectronic devices: semiconductor lasers, Led''s photoconductors, solar cells, photo diodes, modulators. Photoemission. Integrated circuits.', 'College of Engineering', ARRAY['ECE', 'EE', 'MATRL']::TEXT[], 'ECE 162A-B with a minimum grade of C-; open to electrical engineering and materials majors only.', '{"t":"and","kids":[{"t":"course","code":"ECE 162A","concurrent":false},{"t":"course","code":"ECE 162B","concurrent":false}]}'::JSONB, ARRAY['open to electrical engineering and materials majors only', 'with a minimum grade of C-']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20162C'),
  ('ECE 178', 'ECE', '178', 'Introduction to Digital Image and Video Processing', 'INTRO DIG IMAGE', 4, 'Basic concepts in image and video processing. Topics include image formation and sampling, image transforms, image enhancement, and image and video compression including JPEG and MPEG coding standards.', 'College of Engineering', ARRAY['EE', 'CMPEN', 'ECE', 'CMPSC']::TEXT[], 'Open to electrical engineering, computer engineering, and computer science majors with upper-division standing.', NULL, ARRAY['Open to electrical engineering, computer engineering, and computer science majors with upper-division standing']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20178'),
  ('ECE 179D', 'ECE', '179D', 'INTRODUCTION TO ROBOTICS: DYNAMICS AND CONTROL', 'ROBOTICS: CONTROL', 4, 'Dynamic modeling and control methods for robotic systems. LaGrangian method for deriving equations of motion, introduction to the Jacobian, and modeling and control of forces and contact dynamics at a robotic end effector. Laboratories encourage a problem-solving approach to control.', 'College of Engineering', '{}', 'ECE 130A or ME 155A (may be taken concurrently).', '{"t":"or","kids":[{"t":"course","code":"ECE 130A","concurrent":true},{"t":"course","code":"ME 155A","concurrent":true}]}'::JSONB, '{}', ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20179D'),
  ('ECE 179P', 'ECE', '179P', 'Introduction to Robotics: Planning and Kinematics', 'ROBOTICS: PLANNING', 4, 'Motion planning and kinematics topics with an emphasis on geometric reasoning, programming, and matrix computations. Motion planning: configuration spaces, sensor-based planning, decomposition and sampling methods, and advanced planning algorithms. Kinematics: reference frames, rotations and displacements, kinematic motion models.', 'College of Engineering', '{}', 'ENGR 3; and either ME 17 or ECE 130C (may be taken concurrently). Not open for credit to students who have completed Mechanical Engineering 170A or ECE 181A.', '{"t":"and","kids":[{"t":"course","code":"ENGR 3","concurrent":false},{"t":"or","kids":[{"t":"course","code":"ME 17","concurrent":true},{"t":"course","code":"ECE 130C","concurrent":true}]}]}'::JSONB, ARRAY['Not open for credit to students who have completed Mechanical Engineering 170A or ECE 181A']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20179P'),
  ('ECE 180', 'ECE', '180', 'INTRODUCTION TO DEEP LEARNING', 'INTRO DEEP LEARNING', 0, 'Introduction to multilayered neural networks, early models of perceptrons and associative memory; back-propagation learning; convolutional neural networks; recurrent neural networks; attention models; applications to natural language processing and computer vision.', 'College of Engineering', ARRAY['EE', 'CMPEN', 'CMPSC']::TEXT[], 'Open to EE, Computer Engineering and Computer Science with upper-division standing.', NULL, ARRAY['Open to EE, Computer Engineering and Computer Science with upper-division standing']::TEXT[], ARRAY['Fall', 'Spring']::TEXT[], 'uncertain', ARRAY['ECE department grid marks Fall 2026-27 as not offered']::TEXT[], 'ECE Undergraduate Courses 2026-27 grid + Schedule of Classes history', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20180'),
  ('ECE 181', 'ECE', '181', 'Introduction to Computer Vision', 'INTRO COMP VISION', 4, 'Overview of computer vision problems and techniques for analyzing the content of images and video. Topics include image formation, edge detection, image segmentation, pattern recognition, texture analysis, optical flow, stereo vision, shape representation and recovery techniques, issues in object recognition, and case studies of practical vision systems.', 'College of Engineering', ARRAY['CHEME', 'CMPEN', 'CPSCI', 'EE', 'ME', 'CMPSC']::TEXT[], 'Upper-division standing in Electrical Engineering, Computer Engineering, Computer Science, Chemical Engineering or Mechanical Engineering.', NULL, ARRAY['Upper-division standing in Electrical Engineering, Computer Engineering, Computer Science, Chemical Engineering or Mechanical Engineering']::TEXT[], ARRAY['Fall', 'Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20181'),
  ('ECE 183', 'ECE', '183', 'Nonlinear Phenomena', 'NONLINEAR PHENOMENA', 4, 'An introduction to nonlinear phenomena. Flows and bifurcations in one and two dimensions, chaos, fractals, strange attractors. Applications to physics, engineering, chemistry, and biology.', 'College of Engineering', '{}', 'Physics 105A or Physics 103; or ME 163 or upper-division standing in ECE.', NULL, ARRAY['upper-division standing in ECE', '[curated] ''or upper-division standing in ECE'' is an alternative to every listed course, so no course is strictly required for ECE majors.']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20183'),
  ('ECE 184', 'ECE', '184', 'Introduction to Video Game Development', 'Intro to Game Dev', 5, 'Introduction to game design, video game architectures, large-scale software design patterns,
game aesthetics, user interface design, and playtesting, all within the Unity3D framework.
Quarter culminates in a high-quality video game suitable for public release. Pre-requisite for
the advanced game-development sequence.', 'College of Engineering', ARRAY['CMPEN', 'EE   ', 'CMPSC']::TEXT[], 'CS 130A and CS 130B or significant programming experience in large software systems.', '{"t":"and","kids":[{"t":"course","code":"CMPSC 130A","concurrent":false},{"t":"course","code":"CMPSC 130B","concurrent":false}]}'::JSONB, ARRAY['significant programming experience in large software systems']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20184'),
  ('ECE 186', 'ECE', '186', 'Probabilistic Machine Learning', 'PROB MACH LEARN', 4, 'An introductory course to topics in machine learning studied from a probability theory viewpoint. Covers an overview of basic probability, inference and estimation, regression algorithms, Markov chains, inference for Markov models and the EM algorithm, Markov decision process, and reinforcement learning. In addition to covering mathematical and algorithmic details, the course includes several hands-on projects to implement the machine learning algorithms.', 'College of Engineering', '{}', 'ECE 139 or PSTAT 120A or equivalent.', '{"t":"or","kids":[{"t":"course","code":"ECE 139","concurrent":false},{"t":"course","code":"PSTAT 120A","concurrent":false}]}'::JSONB, ARRAY['or equivalent']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20186'),
  ('ECE 188A', 'ECE', '188A', 'Senior Electrical Engineering Project', 'SENIOR EE PROJECT', 4, 'Student groups design a significant project based on the knowledge and skills acquired in earlier coursework and integrate their technical knowledge through a practical design experience. The project is evaluated through written reports, oral presentations, and demonstrations of performance.', 'College of Engineering', ARRAY['EE', 'CMPEN']::TEXT[], 'ECE 153A or ECE 153B. ECE 153A may be taken concurrently with ECE 188A.', '{"t":"or","kids":[{"t":"course","code":"ECE 153A","concurrent":true},{"t":"course","code":"ECE 153B","concurrent":false}]}'::JSONB, ARRAY['[curated] Second sentence grants concurrency for ECE 153A only; the parser read it as an extra conjunct.']::TEXT[], ARRAY['Fall']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20188A'),
  ('ECE 188B', 'ECE', '188B', 'Senior Electrical Engineering Project', 'SENIOR EE PROJECT', 4, 'Student groups design a significant project based on the knowledge and skills acquired in earlier coursework and integrate their technical knowledge through a practical design experience. The project is evaluated through written reports, oral presentations, and demonstrations of performance.', 'College of Engineering', ARRAY['EE', 'CMPEN']::TEXT[], 'ECE 188A with a minimum grade of C-.', '{"t":"course","code":"ECE 188A","concurrent":false}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20188B'),
  ('ECE 188C', 'ECE', '188C', 'Senior Electrical Engineering Project', 'SENIOR EE PROJECT', 4, 'Student groups design a significant project based on the knowledge and skills acquired in earlier coursework and integrate their technical knowledge through a practical design experience. The project is evaluated through written reports, oral presentations, and demonstrations of performance.', 'College of Engineering', ARRAY['EE', 'CMPEN']::TEXT[], 'ECE 188B with a minimum grade of C-.', '{"t":"course","code":"ECE 188B","concurrent":false}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20188C'),
  ('ECE 189A', 'ECE', '189A', 'Senior Computer Systems Project', 'SR CMPTR PRJCT', 4, 'Student groups design a significant computer-based project. The focus will be on designing a significant project based on the knowledge and skills acquired in earlier coursework. Groups work independently with interaction among groups via interface specifications and informal meetings. The project is evaluated through successful completion of milestones and individual/group project reports and presentations.', 'College of Engineering', ARRAY['ECE', 'CMPSC', 'CMPEN', 'CPSCI']::TEXT[], 'ECE 153B with a minimum grade of C-; senior standing in Computer Engineering, Computer Science or EE.', '{"t":"course","code":"ECE 153B","concurrent":false}'::JSONB, ARRAY['senior standing in Computer Engineering, Computer Science or EE', 'with a minimum grade of C-']::TEXT[], ARRAY['Fall']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20189A'),
  ('ECE 189B', 'ECE', '189B', 'Senior Computer Systems Project', 'SR CMPTR PRJCT', 4, 'Student groups design a significant computer-based project. Focus will be on building and implementing an embedded hardware system. Each group works independently. The project is evaluated through project reports, achieving milestones and through successful demonstration of hardware functionality.', 'College of Engineering', ARRAY['ECE', 'CMPSC', 'CMPEN', 'CPSCI']::TEXT[], 'ECE 189A with a minimum grade of a C- or better; senior standing in Computer Engineering, Computer Science or ECE.', '{"t":"course","code":"ECE 189A","concurrent":false}'::JSONB, ARRAY['senior standing in Computer Engineering, Computer Science or ECE', 'with a minimum grade of a']::TEXT[], ARRAY['Winter']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20189B'),
  ('ECE 189C', 'ECE', '189C', 'Senior Computer Systems Project', 'SR CMPTR PROJ', 4, 'Student groups design a significant computer-based project. The focus in this course will be on the integration of both hardware and software components. Students continue to work in groups. Apart from project reports and presentations, the evaluation will be based on successful demonstration of both hardware and software aspects of the project.', 'College of Engineering', '{}', 'ECE 189B with a minimum grade of a C- or better ; senior standing in Computer Engineering, Computer Science, or EE.', '{"t":"course","code":"ECE 189B","concurrent":false}'::JSONB, ARRAY['senior standing in Computer Engineering, Computer Science, or EE', 'with a minimum grade of a']::TEXT[], ARRAY['Spring']::TEXT[], 'scheduled', '{}', 'ECE Undergraduate Courses 2026-27 grid', 'https://www.ece.ucsb.edu/undergrad/courses', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ECE%20189C'),
  ('ENGR 3', 'ENGR', '3', 'Introduction to Programming', 'INTRO TO PROG', 3, 'General philosophy of programming and problem-solving. Students will be introduced to the programming language MATLAB. Specific areas of study will include algorithms, basic decision structures, arrays, matrices, and graphing.', 'College of Engineering', ARRAY['CHEME', 'EE', 'ME']::TEXT[], '', NULL, '{}', ARRAY['Fall', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ENGR%203'),
  ('ENGR 101', 'ENGR', '101', 'Ethics in Engineering', 'ETHICS IN ENGR', 3, 'The nature of moral value, normative judgment and moral reasoning. Theories of moral value. The engineer''s role in society. Ethics in professional practice. Safety, risk, responsibility. Morality and career choice. Code of ethics. Case studies facilitate the comprehension of the concepts introduced.', 'College of Engineering', '{}', 'Senior standing in engineering.', NULL, ARRAY['Senior standing in engineering']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ENGR%20101'),
  ('MATH 2A', 'MATH', '2A', 'Calculus with Algebra and Trigonometry', 'CALC W/ ALG & TRIG', 5, 'Math 3A with precalculus: A function approach integrating algebra, trigonometry, and differential calculus. Topics include: one-on-one and onto functions; inverse functions; properties and graphs of polynomial, rational, exponential, and logarithmic functions; properties and graphs of trigonometric functions; analytic geometry; functions and limits; derivatives; techniques and applications of differentiation; introduction to integration; logarithmic and trigonometric functions.', 'College of Letters and Science', '{}', 'Qualifying score on the Mathematics Placement Exam.', NULL, ARRAY['Qualifying score on the Mathematics Placement Exam']::TEXT[], ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATH%202A'),
  ('MATH 2B', 'MATH', '2B', 'Calculus with Algebra and Trigonometry', 'CALC W/ ALG & TRIG', 5, 'Math 3B with precalculus: A continued review of relevant topics from precalculus (see Math 2A); integral calculus, including definite and indefinite integrals; techniques of integration, introduction to sequences and series; with applications in mathematics and physics.', 'College of Letters and Science', '{}', 'Mathematics 2A with a minimum grade of C.', '{"t":"course","code":"MATH 2A","concurrent":false}'::JSONB, ARRAY['with a minimum grade of C']::TEXT[], ARRAY['Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATH%202B'),
  ('MATH 3A', 'MATH', '3A', 'Calculus with Applications, First Course', 'CALC WITH APPLI 1', 4, 'Differential Calculus including analytic geometry, functions and limits, derivatives, techniques and applications of differentiation; introduction to integration; logarithmic and trigonometric functions.', 'College of Letters and Science', '{}', 'Qualifying score on the Mathematics Placement Exam.', NULL, ARRAY['Qualifying score on the Mathematics Placement Exam']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATH%203A'),
  ('MATH 3B', 'MATH', '3B', 'Calculus with Applications, Second Course', 'CALC WITH APPLI 2', 4, 'Integral calculus including definite and indefinite integrals, techniques of integration; introduction to sequences and series; with applications in mathematics and physics.', 'College of Letters and Science', '{}', 'Mathematics 3A with a minimum grade of C.', '{"t":"course","code":"MATH 3A","concurrent":false}'::JSONB, ARRAY['with a minimum grade of C']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATH%203B'),
  ('MATH 4A', 'MATH', '4A', 'Linear Algebra with Applications', 'LIN ALG W/APPS', 4, 'Systems of linear equations, matrix algebra, determinants, vector spaces and subspaces, basis and dimension, linear transformations, eigenvalues and eigenvectors, diagonalization, and orthogonality.', 'College of Letters and Science', '{}', 'Math 2B or 3B or 3BI with a minimum grade of C.', '{"t":"or","kids":[{"t":"course","code":"MATH 2B","concurrent":false},{"t":"course","code":"MATH 3B","concurrent":false},{"t":"course","code":"MATH 3BI","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATH%204A'),
  ('MATH 4AI', 'MATH', '4AI', 'Inquiry Based Linear Algebra', 'INQ BASED LIN ALG', 4, 'Honors version of Mathematics 4A. Mathematical inquiry course is developed through problem solving and discovery.', 'College of Letters and Science', '{}', 'Mathematics 3B or Mathematics 3BI with a minimum grade of C.', '{"t":"or","kids":[{"t":"course","code":"MATH 3B","concurrent":false},{"t":"course","code":"MATH 3BI","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATH%204AI'),
  ('MATH 4B', 'MATH', '4B', 'Differential Equations', 'DIFF EQUATIONS', 4, 'First and second order differential equations, separation of variables, linear differential equations, systems of first order equations, nonlinear differential equations and stability.', 'College of Letters and Science', '{}', 'Math 4A or Math 4AI with a minimum grade of C.', '{"t":"or","kids":[{"t":"course","code":"MATH 4A","concurrent":false},{"t":"course","code":"MATH 4AI","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATH%204B'),
  ('MATH 4BI', 'MATH', '4BI', 'Inquiry Based Differential Equations', 'INQ BASED DIFF EQU', 4, 'Honors version of Mathematics 4B. Mathematical inquiry course is developed through problem solving and discovery.', 'College of Letters and Science', '{}', 'Mathematics 3C, 3CI, 4A, or 4AI with a minimum grade of C.', '{"t":"or","kids":[{"t":"course","code":"MATH 3C","concurrent":false},{"t":"course","code":"MATH 3CI","concurrent":false},{"t":"course","code":"MATH 4A","concurrent":false},{"t":"course","code":"MATH 4AI","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATH%204BI'),
  ('MATH 6A', 'MATH', '6A', 'Vector Calculus with Applications, First Course', 'VECTOR CALCULUS 1', 4, 'Calculus of functions of several variables, vector valued functions of one variable, derivative and integrals of vector functions, double and triple integrals, properties and applications of integrals, change of variables.', 'College of Letters and Science', '{}', 'Mathematics 4A (or 4AI) with a letter grade of C or better.', '{"t":"or","kids":[{"t":"course","code":"MATH 4A","concurrent":false},{"t":"course","code":"MATH 4AI","concurrent":false}]}'::JSONB, ARRAY['with a letter grade of C or better']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATH%206A'),
  ('MATH 6B', 'MATH', '6B', 'Vector calculus with Applications, Second Course', 'VECTOR CALCULUS 2', 4, 'Scalar and vector fields, integration along paths, integration over surfaces and solid regions, integral theorems of vector calculus, Fourier series, partial differential equations.', 'College of Letters and Science', '{}', 'Mathematics 4B (or 4BI) and Mathematics 6A, each with a minimum grade of C.', '{"t":"and","kids":[{"t":"or","kids":[{"t":"course","code":"MATH 4B","concurrent":false},{"t":"course","code":"MATH 4BI","concurrent":false}]},{"t":"course","code":"MATH 6A","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATH%206B'),
  ('MATH 8', 'MATH', '8', 'Transition to Higher Mathematics', 'TRANS HIGHER MATH', 5, 'Introduction to the elements of propositional logic, techniques of mathematical proof, and fundamental mathematical structures, including sets, functions, relations, and other topics as time permits. Mastery of this material is essential for students planning to major in mathematics.', 'College of Letters and Science', '{}', 'Mathematics 4A or 4AI or 4B or 4BI or 6A or 6B with a grade of B or better.', '{"t":"or","kids":[{"t":"course","code":"MATH 4A","concurrent":false},{"t":"course","code":"MATH 4AI","concurrent":false},{"t":"course","code":"MATH 4B","concurrent":false},{"t":"course","code":"MATH 4BI","concurrent":false},{"t":"course","code":"MATH 6A","concurrent":false},{"t":"course","code":"MATH 6B","concurrent":false}]}'::JSONB, ARRAY['with a grade of B or better']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATH%208'),
  ('MATRL 100A', 'MATRL', '100A', 'Structure and Properties I', 'STRUCT. & PROP. I', 3, 'An introduction to materials in modern technology. The internal structure of materials and its underlying principles: bonding, spatial organization of atoms and molecules, structural defects. Electricial, magnetic and optical properties of materials, and their relationship with structure.', 'College of Engineering', '{}', 'Chemistry 1A-B and Mathematics 4B, 6A, 6B', '{"t":"and","kids":[{"t":"course","code":"CHEM 1A","concurrent":false},{"t":"course","code":"CHEM 1B","concurrent":false},{"t":"course","code":"MATH 4B","concurrent":false},{"t":"course","code":"MATH 6A","concurrent":false},{"t":"course","code":"MATH 6B","concurrent":false}]}'::JSONB, '{}', ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATRL%20100A'),
  ('MATRL 100B', 'MATRL', '100B', 'Structures and Properties II', 'STRUCT & PROP II', 3, 'Mechanical properties of engineering materials and their relationship to bonding and structure. Elastic, flow, and fracture behavior; time dependent deformation and failure. Stiffening, strengthening, and toughening mechanisms. Thermo-mechanical interactions in materials.', 'College of Engineering', '{}', 'Materials 100A.', '{"t":"course","code":"MATRL 100A","concurrent":false}'::JSONB, '{}', ARRAY['Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATRL%20100B'),
  ('MATRL 100C', 'MATRL', '100C', 'Fundamentals of Structural Evolution', 'FUND OF STRUC EVOL', 3, 'An introduction to the thermodynamic and kinetic principles governing structural evolution in materials. Phase equilibria, diffusion and structural transformations. Metastable structures in materials. Self-assembling systems. Structural control through processing and/ or imposed fields. Environmental effects on structure and properties.', 'College of Engineering', '{}', 'Materials 100A and Materials 100B.', '{"t":"and","kids":[{"t":"course","code":"MATRL 100A","concurrent":false},{"t":"course","code":"MATRL 100B","concurrent":false}]}'::JSONB, '{}', ARRAY['Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATRL%20100C'),
  ('MATRL 101', 'MATRL', '101', 'Introduction to the Structure and Properties of Materials', 'INTRO STRUCT & PROP', 3, 'Introduction to the structure of engineering materials and its relationship with their mechanical properties. Structure of solids and defects. Concepts of microstructure and origins. Elastic, plastic flow and fracture properties. Mechanisms of deformation and failure. Stiffening, strengthening, and toughening mechanisms.', 'College of Engineering', '{}', '', NULL, '{}', ARRAY['Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATRL%20101'),
  ('MATRL 162A', 'MATRL', '162A', 'The Quantum Description of Electronic Materials', 'QUANTUM ELEC MATRLS', 4, 'Electrons as particles and waves, Schrodinger''s equation and illustrative solutions. Tunneling. Atomic structures, the exclusion principle and the periodic table. Bonds. Free electrons in metals, periodic potentials and energy bands.', 'College of Engineering', ARRAY['ECE', 'MATRL', 'EE']::TEXT[], 'ECE 130A-B and 134 with a minimum grade of C- in all; open to EE, senior students in the BS/MS programs and Materials graduate students only.', '{"t":"and","kids":[{"t":"course","code":"ECE 130A","concurrent":false},{"t":"course","code":"ECE 130B","concurrent":false},{"t":"course","code":"ECE 134","concurrent":false}]}'::JSONB, ARRAY['open to EE, senior students in the BS/MS programs and Materials graduate students only', 'with a minimum grade of C-']::TEXT[], ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATRL%20162A'),
  ('MATRL 162B', 'MATRL', '162B', 'Fundamentals of the Solid State', 'FUND SOLID STATE', 4, 'Crystal lattices and the structure of solids, with emphasis on seminconductors. Lattice vibartations. Electronic states and energy bands. Electrical and thermal conduction. Dielectic and optical properties. Semiconductor devices: diffusion, P-N junctions and diode behavior.', 'College of Engineering', ARRAY['ECE', 'MATRL', 'EE']::TEXT[], 'ECE 162A with a minimum grade of C-; open to EE, senior students in the BS/MS programs and Materials graduate students only.', '{"t":"course","code":"ECE 162A","concurrent":false}'::JSONB, ARRAY['open to EE, senior students in the BS/MS programs and Materials graduate students only', 'with a minimum grade of C-']::TEXT[], ARRAY['Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/MATRL%20162B'),
  ('ME 14', 'ME', '14', 'Statics', 'STATICS', 4, 'Introduction to applied mechanics. Forces, moments, couples, and resultants; vector algebra; construction of free body diagrams; equilibrium in 2- and 3-dimensions; analysis of frames, machines, trusses and beams; distributed forces; friction.', 'College of Engineering', ARRAY['ME']::TEXT[], 'Math 2B, or Math 3B, or AP Calculus AB with a score of 5, or AP Calculus BC with a score of 3 or better; and Physics 7A, or Physics 1', '{"t":"and","kids":[{"t":"or","kids":[{"t":"course","code":"MATH 2B","concurrent":false},{"t":"course","code":"MATH 3B","concurrent":false}]},{"t":"or","kids":[{"t":"course","code":"PHYS 7A","concurrent":false},{"t":"course","code":"PHYS 1","concurrent":false}]}]}'::JSONB, ARRAY['AP Calculus AB with a score of 5', 'AP Calculus BC with a score of 3']::TEXT[], ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ME%2014'),
  ('ME 16', 'ME', '16', 'Engineering Mechanics: Dynamics', 'ENGR MECH: DYNAMICS', 4, 'Vectorial kinematics of particles. Coordinate systems, moving frames, relative and constrained motion. Dynamics of particles and systems of particles. Energy and momentum methods. Collisions. Planar kinematics and kinematics of rigid bodies. Energy and momentum methods for rigid body systems.', 'College of Engineering', ARRAY['ME']::TEXT[], 'Physics 7A or Physics 2, and ME 14 with a minimum grade of C-, and Math 6B or Math 5C (may be taken concurrently); open to ME majors only.', '{"t":"and","kids":[{"t":"or","kids":[{"t":"course","code":"PHYS 7A","concurrent":false},{"t":"course","code":"PHYS 2","concurrent":false}]},{"t":"course","code":"ME 14","concurrent":false},{"t":"or","kids":[{"t":"course","code":"MATH 6B","concurrent":true},{"t":"course","code":"MATH 5C","concurrent":true}]}]}'::JSONB, ARRAY['open to ME majors only', 'with a minimum grade of C-']::TEXT[], ARRAY['Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ME%2016'),
  ('ME 17', 'ME', '17', 'Mathematics of Engineering', 'MATH OF ENGR', 3, 'Introduction to basic numerical and analytical methods, with implementation using MATLAB. Topics include a Matlab review, ordinary differential equations, partial differential equations and boundary conditions, eigenvalue/eigenvectors. Graphic and visualization tools in Matlab.', 'College of Engineering', ARRAY['ME']::TEXT[], 'Engineering 3; open to ME majors only.', '{"t":"course","code":"ENGR 3","concurrent":false}'::JSONB, ARRAY['open to ME majors only']::TEXT[], ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ME%2017'),
  ('ME 103', 'ME', '103', 'Dynamical Systems', 'DYNAMICAL SYSTEMS', 4, 'Equations of Motion for Mechanical, Electrical, Heat, Fluid, and Control
Systems. Block diagram algebra and interconnections.  Laplace transform.
Transfer functions and dynamic stability. First and second order systems.
Frequency response. Introduction to mechanical vibrations and feedback
control design.', 'College of Engineering', '{}', 'Math 6B and ME 16', '{"t":"and","kids":[{"t":"course","code":"MATH 6B","concurrent":false},{"t":"course","code":"ME 16","concurrent":false}]}'::JSONB, '{}', ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ME%20103'),
  ('ME 141A', 'ME', '141A', 'Introduction to Nanoelectromechanical and Microelectromechanical systems (NEMS/MEMS)', 'INTRO TO NEMS/MEMS', 3, 'Introduction to nano- and microtechnology. Scaling laws and nanoscale physics are stressed. Individual subjects at the nanoscale including materials, mechanics, photonics, electronics, and fluidics will be described, with an emphasis on differences of behavior at the nanoscale and real-world examples.', 'College of Engineering', '{}', 'ME 16 or ME W 16 and 17; ME 152A and ME 151A (may be concurrent); or ECE 130A & 137A with a minimum grade of C- in both.', '{"t":"or","kids":[{"t":"and","kids":[{"t":"course","code":"ME 16","concurrent":false},{"t":"course","code":"ME 17","concurrent":false},{"t":"course","code":"ME 152A","concurrent":false},{"t":"course","code":"ME 151A","concurrent":true}]},{"t":"and","kids":[{"t":"course","code":"ECE 130A","concurrent":false},{"t":"course","code":"ECE 137A","concurrent":false}]}]}'::JSONB, ARRAY['with a minimum grade of C-', '[curated] Cross-listed with ECE 141A; same trailing-''or'' ambiguity.']::TEXT[], ARRAY['Fall', 'Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ME%20141A'),
  ('ME 151A', 'ME', '151A', 'Thermosciences 1', 'THERMOSCIENCES 1', 4, 'Basic concepts in thermodynamics, system analysis, energy, thermodynamic laws, and cycles.', 'College of Engineering', ARRAY['ME']::TEXT[], 'Physics 7D or Physics 2, and ME 14 with a minimum grade of C-, and Math 6B or Math 5C', '{"t":"and","kids":[{"t":"or","kids":[{"t":"course","code":"PHYS 7D","concurrent":false},{"t":"course","code":"PHYS 2","concurrent":false}]},{"t":"course","code":"ME 14","concurrent":false},{"t":"or","kids":[{"t":"course","code":"MATH 6B","concurrent":false},{"t":"course","code":"MATH 5C","concurrent":false}]}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ME%20151A'),
  ('ME 152A', 'ME', '152A', 'Fluid Mechanics', 'FLUID MECHANICS', 4, 'Introduction to the fundamental concepts in fluid mechanics and basic fluid properties. Basic equations of fluid flow. Dimensional analysis and similitude. Hydrodynamics.', 'College of Engineering', ARRAY['ME']::TEXT[], 'Math 6B or Math 5C, and ME 16 or ME W 16 with a minimum grade of C-, and Physics 7B or Physics 2', '{"t":"and","kids":[{"t":"or","kids":[{"t":"course","code":"MATH 6B","concurrent":false},{"t":"course","code":"MATH 5C","concurrent":false}]},{"t":"course","code":"ME 16","concurrent":false},{"t":"or","kids":[{"t":"course","code":"PHYS 7B","concurrent":false},{"t":"course","code":"PHYS 2","concurrent":false}]}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ME%20152A'),
  ('ME 155A', 'ME', '155A', 'Control System Design', 'CONTROL SYS DESIGN', 3, 'The discipline of control and its application. Dynamics and feedback. The mathematical models: transfer functions and state space descriptions. Simple control design (PID). Assessment of a control problem, specification, fundamental limitations, codesign of system and control.', 'College of Engineering', '{}', 'ME 17 with a minimum grade of C-; ME 103.', '{"t":"and","kids":[{"t":"course","code":"ME 17","concurrent":false},{"t":"course","code":"ME 103","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ME%20155A'),
  ('ME 155B', 'ME', '155B', 'Advanced Control Systems Design', 'ADV CONT SYS DESIGN', 3, 'Dynamic system modeling using state-space methods, controllability and observability, state-space methods for control design including pole placement, and linear quadratic regulator methods. Observers and observer-based feedback controllers. Sampled-data and digital control. Laboratory exercises using MATLAB for simulation and control design.', 'College of Engineering', '{}', 'ME 155A.', '{"t":"course","code":"ME 155A","concurrent":false}'::JSONB, '{}', '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ME%20155B'),
  ('ME 163', 'ME', '163', 'Engineering Mechanics: Vibrations', 'ENGR MECH: VBRTIONS', 3, 'Topics relating to vibration in mechanical systems; exact and approximate methods of analysis, matrix methods, generalized coordinates and Lagrange''s equations, applications of systems. Basic feedback systems and controlled dynamic behavior.', 'College of Engineering', ARRAY['ME']::TEXT[], 'ME 16 or ME W 16 with a minimum grade of C-; open to ME majors only.', '{"t":"course","code":"ME 16","concurrent":false}'::JSONB, ARRAY['open to ME majors only', 'with a minimum grade of C-']::TEXT[], ARRAY['Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/ME%20163'),
  ('PHYS 1', 'PHYS', '1', 'Basic Physics', 'BASIC PHYSICS', 4, 'Introduction to classical mechanics for students in engineering and the physical sciences. Measurement, units, and foundations of physics; vectors; kinematics; circular motion; forces, mass, and Newton''s laws; center of mass; momentum; work and energy; conservation laws; collisions; rotational kinematics.', 'College of Letters and Science', '{}', 'Mathematics 2A or 3A or AP Math AB Exam with a score of 3 or better.', '{"t":"or","kids":[{"t":"course","code":"MATH 2A","concurrent":false},{"t":"course","code":"MATH 3A","concurrent":false}]}'::JSONB, ARRAY['AP Math AB Exam with a score of 3']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/PHYS%201'),
  ('PHYS 2', 'PHYS', '2', 'Basic Physics', 'BASIC PHYSICS', 4, 'Rotational dynamics and angular momentum; equilibrium and elasticity; periodic motion including LRC electrical circuits; gravitation; fluid mechanics; temperature; thermal expansion; heat and the first law of thermodynamics; heat conduction; kinetic theory of gases; entropy and the second law; heat engines.', 'College of Letters and Science', '{}', 'Physics 1 with a grade of C- or better; Mathematics 2A-B or 3A-B or AP Math BC exam with a score of 3 or better.', '{"t":"and","kids":[{"t":"course","code":"PHYS 1","concurrent":false},{"t":"or","kids":[{"t":"and","kids":[{"t":"course","code":"MATH 2A","concurrent":false},{"t":"course","code":"MATH 2B","concurrent":false}]},{"t":"and","kids":[{"t":"course","code":"MATH 3A","concurrent":false},{"t":"course","code":"MATH 3B","concurrent":false}]}]}]}'::JSONB, ARRAY['with a grade of C- or better', 'AP Math BC exam with a score of 3']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/PHYS%202'),
  ('PHYS 3', 'PHYS', '3', 'Basic Physics', 'BASIC PHYSICS', 3, 'Mechanical waves, wave interference and normal modes, sound and hearing, electric field, Gauss''s law, electric potential, capacitance and dielectrics, current, resistance, electromotive force, DC circuits.', 'College of Letters and Science', '{}', 'Physics 2 with a grade of C- or better; Mathematics 2A-B or 3A-B (AP Math BC Exam score of 3 or better) and 4A.', '{"t":"and","kids":[{"t":"course","code":"PHYS 2","concurrent":false},{"t":"or","kids":[{"t":"and","kids":[{"t":"course","code":"MATH 2A","concurrent":false},{"t":"course","code":"MATH 2B","concurrent":false}]},{"t":"and","kids":[{"t":"course","code":"MATH 3A","concurrent":false},{"t":"course","code":"MATH 3B","concurrent":false}]}]},{"t":"course","code":"MATH 4A","concurrent":false}]}'::JSONB, ARRAY['with a grade of C- or better', '(AP Math BC Exam score of 3  )']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/PHYS%203'),
  ('PHYS 4', 'PHYS', '4', 'Basic Physics', 'BASIC PHYSICS', 3, 'Magnetic fields, electromagnetic induction and inductance, AC circuits, Maxwell''s equations, electromagnetic waves, light and geometrical optics, interference and diffraction.', 'College of Letters and Science', '{}', 'Physics 3 with a grade of C- or better.', '{"t":"course","code":"PHYS 3","concurrent":false}'::JSONB, ARRAY['with a grade of C- or better']::TEXT[], '{}', 'unknown', ARRAY['No offering found in the ECE 2026-27 grid or in the Schedule of Classes for Fall 2024 - Fall 2026']::TEXT[], 'no published quarter data found', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/PHYS%204'),
