  ('PHYS 7D', 'PHYS', '7D', 'Basic Physics', 'BASIC PHYSICS', 3, 'Temperature, Heat, Laws of Thermodynamics, Special Relativity, Photons, Wave-particle duality of Matter, Intro to Quantum Mechanics, Schrodinger Equation in 1D, Hydrogen Atom.', 'College of Letters and Science', '{}', 'Physics 7C with a grade of C- or better; Mathematics 2A-B or 3A-B (AP Math BC Exam score of 3 or better) and 4A.', '{"t":"and","kids":[{"t":"course","code":"PHYS 7C","concurrent":false},{"t":"or","kids":[{"t":"and","kids":[{"t":"course","code":"MATH 2A","concurrent":false},{"t":"course","code":"MATH 2B","concurrent":false}]},{"t":"and","kids":[{"t":"course","code":"MATH 3A","concurrent":false},{"t":"course","code":"MATH 3B","concurrent":false}]}]},{"t":"course","code":"MATH 4A","concurrent":false}]}'::JSONB, ARRAY['with a grade of C- or better', '(AP Math BC Exam score of 3  )']::TEXT[], ARRAY['Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/PHYS%207D'),
  ('PHYS 7L', 'PHYS', '7L', 'Physics Laboratory', 'PHYSICS LAB', 1, 'Periodic motion, sound, and basic electronics, while emphasizing good laboratory techniques such as uncertainty propagation, statistical analysis, developing and testing models, and good report writing.', 'College of Letters and Science', '{}', 'Physics 7B; Co-requisite: Physics 7C', '{"t":"and","kids":[{"t":"course","code":"PHYS 7B","concurrent":false},{"t":"course","code":"PHYS 7C","concurrent":true}]}'::JSONB, '{}', ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/PHYS%207L'),
  ('PHYS 8', 'PHYS', '8', 'Introduction to Mathematical Methods for Physics', 'INTRO MATH METHODS', 5, 'Single variable functions, derivatives and integrals with applications to kinematics. Taylor series. Introduction to ordinary differential equations and Newtons second law as an ODE. Vectors and scalars with physics applications. Dot and cross products. Matrices and determinants. Unit circle and trigonometric identities. Polar coordinates and kinematics in polar coordinates.', 'College of Letters and Science', '{}', '', NULL, '{}', ARRAY['Fall']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/PHYS%208'),
  ('PHYS 21', 'PHYS', '21', 'General Physics', 'GEN PHYS', 4, 'Classical mechanics, kinematics, vectors, Newtons laws, work and energy, conservation laws, rotational kinematics.', 'College of Letters and Science', '{}', 'Mathematics 2A/3A and Mathematics 2B/3B or Physics 8 or AP Calculus BC Exam score of 5.', '{"t":"and","kids":[{"t":"or","kids":[{"t":"course","code":"MATH 2A","concurrent":false},{"t":"course","code":"MATH 3A","concurrent":false}]},{"t":"or","kids":[{"t":"course","code":"MATH 2B","concurrent":false},{"t":"course","code":"MATH 3B","concurrent":false},{"t":"course","code":"PHYS 8","concurrent":false}]}]}'::JSONB, ARRAY['AP Calculus BC Exam score of 5']::TEXT[], ARRAY['Fall', 'Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/PHYS%2021'),
  ('PHYS 22', 'PHYS', '22', 'General Physics', 'GEN PHYS', 4, 'Rotational dynamics, fluid mechanics, gravitation, periodic motion, temperature and heat, thermodynamics.', 'College of Letters and Science', '{}', 'Physics 21 with a grade of C- or better.', '{"t":"course","code":"PHYS 21","concurrent":false}'::JSONB, ARRAY['with a grade of C- or better']::TEXT[], ARRAY['Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/PHYS%2022'),
  ('PHYS 23', 'PHYS', '23', 'General Physics', 'GEN PHYS', 4, 'Mechanical waves, sound, electric charge and electric field, Gauss Law, electric potential, capacitance and dielectrics, current, resistance, electromotive force, DC circuits.', 'College of Letters and Science', '{}', 'Physics 22 with a minimum grade of C- or better.', '{"t":"course","code":"PHYS 22","concurrent":false}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Fall', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/PHYS%2023'),
  ('PHYS 24', 'PHYS', '24', 'General Physics', 'GEN PHYS', 4, 'Magnetic fields, electromagnetic induction and inductance, AC circuits, Maxwell''s equations, electromagnetic waves, light and geometrical optics, interference and diffraction.', 'College of Letters and Science', '{}', 'Physics 23 with a minimum grade of C-; Mathematics 4A.', '{"t":"and","kids":[{"t":"course","code":"PHYS 23","concurrent":false},{"t":"course","code":"MATH 4A","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Fall', 'Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/PHYS%2024'),
  ('PHYS 25', 'PHYS', '25', 'General Physics', 'GEN PHYS', 4, 'Special relativity, blackbody radiation, Compton scattering, photoelectric effect, Bohr model, quantum mechanics, molecules, condensed matter, nuclear physics, elementary particles.', 'College of Letters and Science', '{}', 'Physics 24 with a minimum grade of C-; Mathematics 6A.', '{"t":"and","kids":[{"t":"course","code":"PHYS 24","concurrent":false},{"t":"course","code":"MATH 6A","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/PHYS%2025'),
  ('PHYS 103', 'PHYS', '103', 'Intermediate Mechanics and Special Relativity', 'INT MECH & SPEC REL', 4, 'Newtonian mechanics in 3D. Conservation laws. Complex numbers. Oscillations. Inertial reference frames, Lorentz transformations, relativistic momentum and energy, four-vectors.', 'College of Letters and Science', '{}', 'Physics 2 or 22 with a minimum grade of C-. Mathematics 6A (may be taken concurrently)', '{"t":"and","kids":[{"t":"or","kids":[{"t":"course","code":"PHYS 2","concurrent":false},{"t":"course","code":"PHYS 22","concurrent":false}]},{"t":"course","code":"MATH 6A","concurrent":true}]}'::JSONB, ARRAY['with a minimum grade of C-']::TEXT[], ARRAY['Fall', 'Winter']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/PHYS%20103'),
  ('PSTAT 120A', 'PSTAT', '120A', 'Probability and Statistics', 'PROB & STATISTICS', 4, 'Concepts of probability; random variables; combinatorial probability; discrete and continuous distributions; joint distributions, expected values; moment generating functions; law of large numbers and central limit theorems.', 'College of Letters and Science', '{}', 'Math 3C or Math 4A or Math 4AI or Math 6A or Math 6AI completed with a minimum grade of C or better.', '{"t":"or","kids":[{"t":"course","code":"MATH 3C","concurrent":false},{"t":"course","code":"MATH 4A","concurrent":false},{"t":"course","code":"MATH 4AI","concurrent":false},{"t":"course","code":"MATH 6A","concurrent":false},{"t":"course","code":"MATH 6AI","concurrent":false}]}'::JSONB, ARRAY['with a minimum grade of C']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/PSTAT%20120A'),
  ('TMP 120', 'TMP', '120', 'Fundamentals of Business Strategy', 'BUSINESS STRATEGY', 4, 'An introduction to business strategy, principles and practices required for business success in the competitive market place. Students are exposed to key management theories, models and tools including competitive strategy, finance, planning, new product development, marketing, leadership and others.', 'College of Engineering', '{}', 'Sophomore standing or higher.', NULL, '{}', ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/TMP%20120'),
  ('TMP 122', 'TMP', '122', 'Entrepreneurship', 'ENTREPRENEURSHIP', 4, 'Learn how to start any type of venture; for profit, non-profit, service, sole-proprietorship, with a focus on high-tech ventures. Analysis of new business opportunities, development of customer-centric value propositions, financing, marketing, selling, and protection of intellectual property.', 'College of Engineering', '{}', 'Sophomore standing or higher.', NULL, '{}', ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/TMP%20122'),
  ('WRIT 2', 'WRIT', '2', 'Academic Writing', 'ACADEMIC WRITING', 5, 'A writing course focusing on developing analytical skills, synthesizing multiple sources, sustaining coherent arguments, and revising for clarity of style. Reading and writing assignments are drawn from a range of academic disciplines.', 'College of Letters and Science', '{}', 'Satisfaction of the Entry Level Writing requirement or Linguistics 12 with a grade of "C" or better.', NULL, ARRAY['Satisfaction of the Entry Level Writing requirement or Linguistics 12 with a grade of "C"']::TEXT[], ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/WRIT%202'),
  ('WRIT 50', 'WRIT', '50', 'Writing and the Research Process', 'WRIT & RSRCH PRCESS', 4, 'A writing course addressing the analytical skills underlying the research processes of various academic and professional communities. Sections vary in topic and disciplinary emphasis.', 'College of Letters and Science', '{}', '', NULL, '{}', ARRAY['Fall', 'Winter', 'Spring']::TEXT[], 'historical', '{}', 'UCSB Schedule of Classes, Fall 2024 - Fall 2026', 'https://my.sa.ucsb.edu/public/curriculum/coursesearch.aspx', 'UCSB General Catalog 2025-26', 'https://catalog.ucsb.edu/courses/WRIT%2050');

